function modeCards(active){return Object.entries(MODE_DEFS).map(([id,m])=>`<button class="mode-choice focusable ${active===id?'active':''}" data-focusable data-action="choose-mode" data-mode="${id}"><span class="mode-preview mode-preview-${id}"><i></i><i></i><i></i></span><b>${m.icon} ${escapeHtml(m.name)}</b><small>${escapeHtml(m.desc)}</small></button>`).join('');}


async function fetchOrbit(path, options={}) {
  const method = String(options.method || 'GET').toUpperCase();
  const headers = {...(options.headers||{})};
  if (!['GET','HEAD'].includes(method) && !Object.keys(headers).some(k=>k.toLowerCase()==='content-type')) headers['Content-Type']='application/json';
  return fetch(new URL(path, location.origin).href, {cache:'no-store', ...options, method, headers});
}
async function serverAlive(){try{const r=await fetchOrbit('/api/ping');const b=await r.json();return r.ok&&b?.ok&&b?.name==='ORBIT';}catch(_){return false;}}
async function api(path, options={}) {
  const method=String(options.method||'GET').toUpperCase();
  const retry=options.retryNetwork===true||method==='GET';
  const opts={...options}; delete opts.retryNetwork;
  let response;
  try{response=await fetchOrbit(path,opts);}catch(_){if(retry){await wait(220);try{response=await fetchOrbit(path,opts);}catch(__){}}}
  if(!response){if(!(await serverAlive())) throw new Error('ORBIT perdió la conexión interna. Vuelve a abrir launcher.bat.'); throw new Error('No se pudo comunicar con ORBIT.');}
  let body={}; try{body=await response.json();}catch(_){}
  if(!response.ok||body.ok===false) throw new Error(body.error||`Error ${response.status}`);
  return body;
}

function escapeHtml(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function hashHue(text){let h=0;for(const c of String(text||''))h=(h*31+c.charCodeAt(0))>>>0;return h%360;}
function formatDuration(sec=0){const t=Math.max(0,Number(sec)||0),h=Math.floor(t/3600),m=Math.floor((t%3600)/60);return h?`${h}h ${m}m`:m?`${m} min`:t?'< 1 min':'0 min';}
function formatBytes(bytes=0){let n=Number(bytes)||0;if(n<1024)return `${n} B`;const u=['KB','MB','GB','TB'];let i=0;n/=1024;while(n>=1024&&i<u.length-1){n/=1024;i++;}return `${n.toFixed(n>100?0:1)} ${u[i]}`;}
function formatEta(seconds){if(seconds===null||seconds===undefined||!Number.isFinite(Number(seconds)))return 'Calculando…';const s=Math.max(0,Math.round(Number(seconds)));if(s<=1)return 'menos de 2 s';if(s<60)return `~${s} s`;const m=Math.ceil(s/60);if(m<60)return `~${m} min`;const h=Math.floor(m/60),r=m%60;return `~${h} h${r?` ${r} min`:''}`;}
function formatDate(iso){if(!iso)return 'Nunca';const d=new Date(iso);if(Number.isNaN(d.getTime()))return 'Nunca';return new Intl.DateTimeFormat('es-ES',{day:'2-digit',month:'short',year:'numeric'}).format(d);}
function initials(name){const w=String(name||'Juego').trim().split(/\s+/).filter(Boolean);return w.length>1?(w[0][0]+w.at(-1)[0]).toUpperCase():w[0]?.slice(0,2).toUpperCase()||'OR';}
function mediaUrl(value, version){if(!value)return null;let base=String(value);if(base.startsWith('@launcher/media/'))base='/'+base.replace('@launcher/','');return version?`${base}?v=${encodeURIComponent(version)}`:base;}
function gameById(id){return state.games.find(g=>String(g.id)===String(id));}
function emulatorById(id){return state.emulators.find(e=>String(e.id)===String(id));}
function toast(msg,type=''){const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=msg;$('#toastHost').appendChild(el);setTimeout(()=>el.remove(),4000);}
function showError(err){toast(err?.message||String(err),'error');}
function displayPath(value){return String(value||'');}
function pathInputType(){return 'text';}

function coverMarkup(game){const hue=hashHue(game.id||game.name),url=mediaUrl(game.cover,game.cover_version);return `<div class="cover" style="--c1:hsl(${hue} 46% 35%);--c2:hsl(${(hue+58)%360} 42% 16%)">${url?`<img class="cover-image" src="${escapeHtml(url)}" alt="Carátula de ${escapeHtml(game.name)}" loading="lazy" decoding="async">`:''}${game.favorite?'<span class="favorite-mark">★</span>':''}${url?'':`<span class="cover-initials">${escapeHtml(game.accent||initials(game.name))}</span>`}</div>`;}
function gameCard(game){return `<button class="game-card focusable" data-focusable data-game-id="${escapeHtml(game.id)}"><div class="game-card-art">${coverMarkup(game)}${game.status==='completed'?'<span class="corner-badge">✓</span>':''}</div><div class="game-meta"><h3>${escapeHtml(game.name)}</h3><p><span>${escapeHtml(game.platform||'Otra')}</span><span class="availability ${game.available?'ok':''}">${game.demo?'Demo':game.available?'Disponible':'Revisar'}</span></p></div></button>`;}
function sortGames(games){const a=[...games];if(state.sort==='name')return a.sort((x,y)=>x.name.localeCompare(y.name,'es'));if(state.sort==='time')return a.sort((x,y)=>(y.play_time_seconds||0)-(x.play_time_seconds||0));if(state.sort==='platform')return a.sort((x,y)=>String(x.platform).localeCompare(String(y.platform),'es')||x.name.localeCompare(y.name,'es'));if(state.sort==='added')return a.sort((x,y)=>String(y.added_at||'').localeCompare(String(x.added_at||'')));return a.sort((x,y)=>String(y.last_played||y.added_at||'').localeCompare(String(x.last_played||x.added_at||'')));}
function filteredGames(){const q=state.search.trim().toLowerCase();let games=state.smart==='hidden'?state.games.filter(g=>g.hidden):state.games.filter(g=>!g.hidden);if(state.platform!=='Todos')games=games.filter(g=>g.platform===state.platform);if(state.smart==='favorites')games=games.filter(g=>g.favorite);if(state.smart==='unplayed')games=games.filter(g=>(g.launch_count||0)===0&&!g.demo);if(state.smart==='completed')games=games.filter(g=>g.status==='completed');if(state.smart==='playing')games=games.filter(g=>g.status==='playing');if(state.smart==='missing')games=games.filter(g=>!g.available&&!g.demo);if(q)games=games.filter(g=>`${g.name} ${g.platform} ${g.description||''} ${(g.tags||[]).join(' ')} ${g.genre||''} ${g.developer||''}`.toLowerCase().includes(q));return sortGames(games);}

function renderHero(){const hero=$('#hero');const game=[...state.games].filter(g=>!g.hidden).sort((a,b)=>String(b.last_played||'').localeCompare(String(a.last_played||'')))[0]||state.games.find(g=>!g.hidden);if(!game){hero.style.backgroundImage='';hero.innerHTML=`<div class="hero-content"><p class="eyebrow">EMPIEZA TU BIBLIOTECA</p><h2>Añade tu primer juego</h2><p>ORBIT guardará tu biblioteca en el USB.</p><div class="hero-actions"><button class="primary-button focusable" data-focusable data-action="add-game">＋ Añadir juego</button></div></div>`;return;}const bg=mediaUrl(game.background,game.background_version);hero.style.backgroundImage=bg?`linear-gradient(90deg,rgba(4,7,12,.96) 0%,rgba(4,7,12,.73) 50%,rgba(4,7,12,.30) 100%),url("${bg.replace(/"/g,'%22')}")`:'';hero.style.setProperty('--hero-a',`hsla(${hashHue(game.id)} 88% 62% / .55)`);hero.innerHTML=`<div class="hero-content">${game.logo?`<img class="hero-logo" src="${escapeHtml(mediaUrl(game.logo,game.logo_version))}" alt="${escapeHtml(game.name)}">`:`<h2>${escapeHtml(game.name)}</h2>`}<span class="hero-badge">${game.last_played?'Continuar jugando':game.demo?'Demostración':'En tu biblioteca'}</span><p>${escapeHtml(game.description||`${game.platform} · ${formatDuration(game.play_time_seconds)}`)}</p><div class="hero-actions">${game.demo?'<button class="primary-button focusable" data-focusable data-action="add-game">＋ Añadir juego real</button>':game.available?`<button class="primary-button focusable" data-focusable data-action="launch" data-id="${escapeHtml(game.id)}">▶ Jugar</button>`:'<button class="primary-button" disabled>⚠ No disponible</button>'}<button class="secondary-button focusable" data-focusable data-game-id="${escapeHtml(game.id)}">Detalles</button></div></div>`;}
function section(title,subtitle,games){if(!games.length)return'';return `<section class="section-block"><div class="section-head"><div><h2>${escapeHtml(title)}</h2><p>${escapeHtml(subtitle)}</p></div></div><div class="game-row">${games.map(gameCard).join('')}</div></section>`;}
function renderHome(){renderHero();const active=state.activeSessions||[];const activeHtml=active.length?`<section class="active-session-banner"><div><p class="eyebrow">EN EJECUCIÓN</p><h2>${escapeHtml(active[0].name)}${active.length>1?` +${active.length-1}`:''}</h2></div><div class="button-row">${active.map(x=>`<button class="danger-button focusable" data-focusable data-action="stop-game" data-id="${escapeHtml(x.game_id)}">Cerrar ${escapeHtml(x.name)}</button>`).join('')}</div></section>`:'';const real=state.games.filter(g=>!g.hidden);const recent=[...real].filter(g=>g.last_played).sort((a,b)=>String(b.last_played).localeCompare(String(a.last_played))).slice(0,10);const fav=real.filter(g=>g.favorite).slice(0,10);const unplayed=real.filter(g=>!g.demo&&(g.launch_count||0)===0).slice(0,10);const rows=state.settings.home_rows||['continue','favorites','recent','platforms','unplayed'];let html='';for(const row of rows){if(row==='continue')html+=section('Continuar jugando','Vuelve a tu última partida',recent.slice(0,5));if(row==='favorites')html+=section('Favoritos','Tus imprescindibles',fav);if(row==='recent')html+=section('Añadidos recientemente','Lo último de tu biblioteca',[...real].sort((a,b)=>String(b.added_at||'').localeCompare(String(a.added_at||''))).slice(0,10));if(row==='unplayed')html+=section('Aún no jugados','Algo nuevo para empezar',unplayed);if(row==='platforms'){for(const p of [...new Set(real.map(g=>g.platform))].slice(0,4))html+=section(p,`Juegos de ${p}`,real.filter(g=>g.platform===p).slice(0,10));}}$('#homeSections').innerHTML=activeHtml+(html||'<div class="empty-state">Tu biblioteca está vacía.</div>');}
function renderLibrary(){const smart=[['all','Todos'],['favorites','★ Favoritos'],['playing','Jugando'],['unplayed','No jugados'],['completed','Completados'],['missing','Revisar'],['hidden','Ocultos']];$('#smartFilters').innerHTML=smart.map(([k,l])=>`<button class="chip focusable ${state.smart===k?'active':''}" data-focusable data-smart="${k}">${l}</button>`).join('');const platforms=['Todos',...new Set(state.games.map(g=>g.platform).filter(Boolean))];$('#platformFilters').innerHTML=platforms.map(p=>`<button class="chip focusable ${state.platform===p?'active':''}" data-focusable data-platform="${escapeHtml(p)}">${escapeHtml(p)}</button>`).join('');const games=filteredGames();$('#libraryGrid').innerHTML=games.length?games.map(gameCard).join(''):'<div class="empty-state">No hay juegos con estos filtros.</div>';}
function renderCollections(){const smart=`<div class="collection-grid"><button class="collection-card focusable" data-focusable data-smart="favorites" data-go-library><b>★ Favoritos</b><span>${state.games.filter(g=>g.favorite).length} juegos</span></button><button class="collection-card focusable" data-focusable data-smart="unplayed" data-go-library><b>Sin jugar</b><span>${state.games.filter(g=>!g.demo&&(g.launch_count||0)===0).length} juegos</span></button><button class="collection-card focusable" data-focusable data-smart="completed" data-go-library><b>Completados</b><span>${state.games.filter(g=>g.status==='completed').length} juegos</span></button></div>`;const custom=(state.collections||[]).map(c=>{const games=state.games.filter(g=>(c.game_ids||[]).includes(g.id));return `<section class="section-block collection-section"><div class="section-head"><div><h2>${escapeHtml(c.name)}</h2><p>${games.length} juegos</p></div><div><button class="secondary-button focusable" data-focusable data-action="edit-collection" data-id="${escapeHtml(c.id)}">Editar</button> <button class="icon-button focusable" data-focusable data-action="delete-collection" data-id="${escapeHtml(c.id)}">×</button></div></div><div class="game-row">${games.length?games.map(gameCard).join(''):'<div class="empty-state">Colección vacía</div>'}</div></section>`;}).join('');$('#collectionsContent').innerHTML=`<h2 class="subhead">Colecciones inteligentes</h2>${smart}${custom||'<div class="empty-state">Crea tu primera colección personalizada.</div>'}`;}
function renderSaves(){const games=state.games.filter(g=>!g.demo);const configured=games.filter(g=>g.save_path);$('#savesContent').innerHTML=`<div class="info-banner"><div><p class="eyebrow">PARTIDAS SEGURAS</p><h2>Backups y sincronización</h2><p>ORBIT solo toca rutas de partidas que tú configures. Restaurar o copiar del USB al PC exige confirmación.</p></div></div><div class="game-list-panels">${configured.length?configured.map(g=>`<article class="settings-card save-card"><div class="save-game-head"><div>${coverMarkup(g)}</div><div><h3>${escapeHtml(g.name)}</h3><p>${escapeHtml(displayPath(g.save_path))}</p></div></div><div class="button-row"><button class="secondary-button focusable" data-focusable data-action="backup" data-id="${g.id}">Crear backup</button><button class="secondary-button focusable" data-focusable data-action="backups" data-id="${g.id}">Ver backups</button><button class="secondary-button focusable" data-focusable data-action="sync-to-usb" data-id="${g.id}">PC → USB</button><button class="secondary-button focusable" data-focusable data-action="sync-to-pc" data-id="${g.id}">USB → PC</button></div></article>`).join(''):'<div class="empty-state">Configura la ruta de partidas desde Editar juego para usar backups.</div>'}</div>`;}
function renderStats(){const s=state.stats||{},by=s.by_platform||{},max=Math.max(1,...Object.values(by));$('#statsContent').innerHTML=`<div class="stat-cards"><div class="stat-card"><small>Tiempo total</small><strong>${formatDuration(s.total_seconds)}</strong></div><div class="stat-card"><small>Juegos</small><strong>${s.games||0}</strong></div><div class="stat-card"><small>Completados</small><strong>${s.completed||0}</strong></div><div class="stat-card"><small>Sesiones</small><strong>${s.sessions||0}</strong></div><div class="stat-card"><small>Sin jugar</small><strong>${s.unplayed||0}</strong></div><div class="stat-card"><small>Sesión más larga</small><strong>${formatDuration(s.longest_session_seconds)}</strong></div></div><div class="stats-columns"><article class="settings-card"><div class="card-heading"><div><p class="eyebrow">BIBLIOTECA</p><h2>Por plataforma</h2></div></div><div class="platform-bars">${Object.entries(by).map(([n,c])=>`<div class="bar-row"><b>${escapeHtml(n)}</b><div class="bar-track"><div class="bar-fill" style="width:${Math.max(4,c/max*100)}%"></div></div><span>${c}</span></div>`).join('')||'<div class="empty-state">Sin datos</div>'}</div></article><article class="settings-card"><div class="card-heading"><div><p class="eyebrow">TIEMPO</p><h2>Más jugados</h2></div></div><div class="list-stack">${(s.most_played||[]).map(g=>`<button class="list-item focusable" data-focusable data-game-id="${g.id}"><span class="list-item-main"><b>${escapeHtml(g.name)}</b><small>${escapeHtml(g.platform)}</small></span><span class="status-badge">${formatDuration(g.play_time_seconds)}</span></button>`).join('')||'<div class="empty-state">Sin datos</div>'}</div></article></div><article class="settings-card history-panel"><div class="card-heading"><div><p class="eyebrow">HISTORIAL</p><h2>Actividad reciente</h2></div></div><div class="list-stack">${(state.history||[]).slice(0,12).map(h=>`<div class="list-item"><div class="list-item-main"><b>${escapeHtml(h.game_name||'Juego')}</b><small>${h.event==='finished'?`Sesión ${formatDuration(h.seconds)}`:'Iniciado'} · ${formatDate(h.at)}</small></div><span class="status-badge">${h.event==='finished'?'Fin':'Inicio'}</span></div>`).join('')||'<div class="empty-state">Sin actividad registrada.</div>'}</div></article>`;}

function profileOptions(){const p=state.profiles?.items||[];return p.map(x=>`<option value="${escapeHtml(x.id)}" ${state.profiles?.active===x.id?'selected':''}>${escapeHtml(x.name)}</option>`).join('');}
const PROFILE_AVATARS = {
  orbit:{icon:'🪐',name:'ORBIT'}, astronaut:{icon:'🧑‍🚀',name:'Astronauta'}, robot:{icon:'🤖',name:'Robot'},
  cat:{icon:'🐱',name:'Gato'}, fox:{icon:'🦊',name:'Zorro'}, arcade:{icon:'👾',name:'Arcade'},
  planet:{icon:'🌍',name:'Planeta'}, star:{icon:'⭐',name:'Estrella'},
};

function activeProfile(){return (state.profiles?.items||[]).find(x=>String(x.id)===String(state.profiles?.active))||(state.profiles?.items||[])[0]||{id:'default',name:'Principal',avatar:'orbit'};}

function applyVirtualKey(key){
  if(key==='DONE'){closeModal();setView('library');return;}
  if(key==='CLEAR')state.search='';else if(key==='BACK')state.search=state.search.slice(0,-1);else if(key==='SPACE')state.search+=' ';else state.search+=key;
  const display=$('#controllerSearchDisplay');if(display)display.textContent=state.search||'…';const input=$('#globalSearch');if(input)input.value=state.search;
}

function avatarMarkup(profile,cls=''){
  const avatar=String(profile?.avatar||'orbit');
  const color=/^#[0-9a-f]{6}$/i.test(profile?.color||'')?profile.color:'#65f4c5';
  if(avatar.startsWith('@launcher/media/profiles/')){
    return `<span class="profile-avatar custom ${cls}" style="--profile-color:${color}"><img src="${escapeHtml(mediaUrl(avatar))}" alt="Foto de ${escapeHtml(profile?.name||'perfil')}"></span>`;
  }
  const def=PROFILE_AVATARS[avatar]||PROFILE_AVATARS.orbit;
  return `<span class="profile-avatar ${cls}" style="--profile-color:${color}" title="${escapeHtml(def.name)}">${def.icon}</span>`;
}

function avatarPicker(selected='orbit'){
  return Object.entries(PROFILE_AVATARS).map(([id,a])=>`<label class="avatar-choice ${selected===id?'active':''}"><input type="radio" name="avatar" value="${id}" ${selected===id?'checked':''}><span>${a.icon}</span><b>${escapeHtml(a.name)}</b></label>`).join('');
}

function bindV030Events(){
  $('#emulatorCenterButton')?.addEventListener('click',emulatorCenterModal);
  document.addEventListener('click',async e=>{
    const gateProfile=e.target.closest('[data-action="gate-profile"]');if(gateProfile){e.preventDefault();try{await selectProfileAndReload(gateProfile.dataset.id,true);}catch(err){showError(err);}return;}
    if(e.target.closest('[data-action="gate-add"]')){e.preventDefault();hideProfileGate();profileCreateModal();return;}
    const menuView=e.target.closest('[data-menu-view]');if(menuView){e.preventDefault();closeControllerMenu();setView(menuView.dataset.menuView);return;}
    if(e.target.closest('[data-menu-close]')){e.preventDefault();closeControllerMenu();return;}
    const vk=e.target.closest('[data-vk]');if(vk){e.preventDefault();applyVirtualKey(vk.dataset.vk);return;}
    const sc=e.target.closest('[data-controller-shortcut]');if(sc){e.preventDefault();const controller=structuredClone(state.settings.controller||{});controller.shortcuts=controller.shortcuts||{};const key=sc.dataset.controllerShortcut;controller.shortcuts[key]=sc.getAttribute('aria-pressed')!=='true';try{await saveSettings({controller});}catch(err){showError(err);}return;}
    const ps=e.target.closest('[data-profile-start-toggle]');if(ps){e.preventDefault();const profiles=structuredClone(state.profiles||{});profiles.select_on_start=ps.getAttribute('aria-pressed')!=='true';try{await saveSettings({profiles});state.profiles=state.settings.profiles||profiles;}catch(err){showError(err);}return;}
  });
}

