function emulatorCatalogMarkup(compact=false){
  const packages=state.emulatorPackages||[];
  if(packages.length){return `<div class="emulator-catalog ${compact?'compact':''}">${packages.map(pkg=>`<article class="emulator-site-card"><div class="emulator-site-icon">${pkg.id==='dolphin'?'🐬':pkg.id==='mame'?'🕹️':pkg.id==='eden'?'🔴':'🎮'}</div><div class="emulator-site-copy"><b>${escapeHtml(pkg.name)}</b><small>${escapeHtml(pkg.platform)}</small><span class="status-badge ${pkg.installed?'ok':''}">${pkg.installed?'Carpeta preparada':'No instalado'}</span>${pkg.notes?`<span class="legacy-note">${escapeHtml(pkg.notes)}</span>`:''}</div><div class="button-row compact">${pkg.auto_install?`<button class="primary-button focusable" data-focusable data-action="install-emulator-package" data-package="${escapeHtml(pkg.id)}">${pkg.installed?'Reinstalar':'Instalar'}</button>`:''}<button class="secondary-button focusable" data-focusable data-action="open-emulator-site" data-site="${escapeHtml(pkg.id)}">Web oficial ↗</button></div></article>`).join('')}</div>`;}
  const items=state.emulatorSites||[];
  return `<div class="emulator-catalog ${compact?'compact':''}">${items.map(site=>`<article class="emulator-site-card"><div class="emulator-site-icon">${site.id==='mame'?'🕹️':site.id==='dolphin'?'🐬':'🎮'}</div><div class="emulator-site-copy"><b>${escapeHtml(site.name)}</b><small>${escapeHtml(site.platform)}</small>${site.status==='legacy'?'<span class="legacy-note">Proyecto legado · sin web oficial activa verificada</span>':''}</div>${site.url?`<button class="secondary-button focusable" data-focusable data-action="open-emulator-site" data-site="${escapeHtml(site.id)}">Web oficial ↗</button>`:'<button class="secondary-button" disabled>Legado</button>'}</article>`).join('')}</div>`;
}
