  $('#profileCreateForm').addEventListener('submit',async e=>{e.preventDefault();try{const fd=Object.fromEntries(new FormData(e.currentTarget));const b=await api('/api/profiles',{method:'POST',body:JSON.stringify(fd)});await loadState();closeModal();await selectProfileAndReload(b.profile.id,false);toast('Perfil creado','success');}catch(err){showError(err);}});
