function profileEditModal(profileId){
  const p=(state.profiles?.items||[]).find(x=>String(x.id)===String(profileId));if(!p)return showError(new Error('Perfil no encontrado.'));
  const custom=String(p.avatar||'').startsWith('@launcher/');const selected=PROFILE_AVATARS[p.avatar]?p.avatar:'';
  openModal(`<form id="profileEditForm"><div class="modal-head"><div><p class="eyebrow">PERFIL</p><h2>Editar ${escapeHtml(p.name)}</h2></div><button type="button" class="icon-button focusable" data-focusable data-action="close-modal">×</button></div><div class="modal-body"><div class="profile-edit-preview">${avatarMarkup(p,'xlarge')}<div><b>${escapeHtml(p.name)}</b><small>${p.avatar?.startsWith('@launcher/')?'Foto personalizada':'Avatar ORBIT'}</small></div></div><div class="field"><label>Nombre</label><input class="focusable" data-focusable name="name" maxlength="40" value="${escapeHtml(p.name)}" required></div><label>Avatar ORBIT</label><div class="avatar-picker">${custom?'<label class="avatar-choice active"><input type="radio" name="avatar" value="__keep__" checked><span>🖼️</span><b>Conservar mi foto</b></label>':''}${avatarPicker(selected)}</div><div class="field"><label>Color identificativo del perfil</label><input class="focusable" data-focusable name="color" type="color" value="${/^#[0-9a-f]{6}$/i.test(p.color||'')?p.color:'#65f4c5'}"></div><div class="button-row"><button type="button" class="secondary-button focusable" data-focusable data-action="profile-photo" data-id="${escapeHtml(p.id)}">🖼 Elegir foto personalizada</button></div></div><div class="modal-actions"><button class="primary-button focusable" data-focusable>Guardar</button></div></form>`);
  $('#profileEditForm').addEventListener('submit',async e=>{e.preventDefault();try{const fd=Object.fromEntries(new FormData(e.currentTarget));if(fd.avatar==='__keep__')delete fd.avatar;await api(`/api/profiles/${p.id}/update`,{method:'POST',body:JSON.stringify(fd)});await loadState();profileManagerModal();toast('Perfil actualizado','success');}catch(err){showError(err);}});
}

function chooseProfilePhoto(profileId){
  openModal(`<div class="modal-head"><div><p class="eyebrow">FOTO DE PERFIL</p><h2>Cambiar foto</h2></div><button type="button" class="icon-button focusable" data-focusable data-action="close-modal">×</button></div><div class="modal-body"><p>Elige una imagen de Windows o del USB. La imagen se guardará dentro de ORBIT y seguirá ahí después de reiniciar.</p><div class="field"><label>Seleccionar imagen</label><input id="orbitProfilePhotoFile" class="focusable" data-focusable type="file" accept="image/*,.bmp,.gif,.avif,.webp,.ico"></div><p class="muted" id="orbitProfilePhotoStatus">Máximo 15 MB · PNG, JPG, WEBP, GIF, BMP y otros formatos compatibles.</p></div><div class="modal-actions"><button type="button" class="secondary-button focusable" data-focusable id="orbitProfilePhotoNative">Selector nativo de Windows</button><button type="button" class="secondary-button focusable" data-focusable data-action="close-modal">Cancelar</button></div>`,true);
  const saved=async()=>{await loadState();profileEditModal(profileId);toast('Foto de perfil guardada','success');};
  $('#orbitProfilePhotoFile')?.addEventListener('change',async e=>{
    const file=e.target.files?.[0];if(!file)return;
    const status=$('#orbitProfilePhotoStatus');if(file.size>15*1024*1024)return toast('La imagen no puede superar 15 MB.','warning');
    if(status)status.textContent='Validando y guardando la imagen…';
    try{
      const response=await fetchOrbit(`/api/profiles/${encodeURIComponent(profileId)}/avatar/upload`,{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:file});
      const payload=await response.json();if(!response.ok||!payload.ok)throw new Error(payload.error||`Error ${response.status}`);
      await saved();
    }catch(err){if(status)status.textContent=`Error: ${err?.message||String(err)}`;showError(err);}
  });
  $('#orbitProfilePhotoNative')?.addEventListener('click',async()=>{
    try{
      const chosen=await api('/api/dialog/cover',{method:'POST',body:'{}'});
      if(!chosen.path)return;
      await api(`/api/profiles/${encodeURIComponent(profileId)}/avatar`,{method:'POST',body:JSON.stringify({path:chosen.path})});
      await saved();
    }catch(err){showError(err);}
  });
}

