function updateControllerTester(gp){
  if(!state.controllerTester||$('#modalBackdrop')?.hidden)return;
  const name=$('#testerGamepadName');if(name)name.textContent=gp?.id||'Sin mando';
  const axes=$('#testerAxes');if(axes)axes.textContent=gp?`Sticks: ${gp.axes.slice(0,4).map(x=>Number(x).toFixed(2)).join(' · ')}`:'Sticks: —';
  $$('[data-test-btn]',$('#modal')).forEach(el=>{const i=Number(el.dataset.testBtn);el.classList.toggle('active',!!gp?.buttons?.[i]?.pressed);});
}

function renderSettings(){
  const s=state.settings||{},controller=s.controller||{},cp=(controller.profiles||[]).find(p=>p.id===controller.active_profile)||(controller.profiles||[])[0]||{};
  const defaults=s.default_emulators||{};
  const emulatorRows=state.emulators.map(e=>`<div class="list-item"><div class="list-item-main"><b>${escapeHtml(e.name)}</b><small>${escapeHtml(e.platform)} · ${escapeHtml(displayPath(e.executable))}</small></div><div class="button-row compact"><span class="status-badge ${e.available?'ok':'warning'}">${e.available?'Listo':'No encontrado'}</span><button class="secondary-button focusable" data-focusable data-action="edit-emulator" data-id="${e.id}">Editar</button><button class="secondary-button focusable" data-focusable data-action="test-emulator" data-id="${e.id}">Probar</button><button class="icon-button focusable" data-focusable data-action="delete-emulator" data-id="${e.id}">×</button></div></div>`).join('')||'<div class="empty-state">Aún no hay emuladores. Usa el asistente para configurar el primero.</div>';
  const folders=(s.game_folders||[]).map(f=>`<div class="list-item"><div class="list-item-main"><b>${escapeHtml(f.platform)}</b><small>${escapeHtml(displayPath(f.path))}</small></div><span class="status-badge">Escaneo</span></div>`).join('')||'<div class="empty-state">No hay carpetas configuradas.</div>';
  const defaultRows=[...new Set(state.emulators.map(e=>e.platform))].map(p=>`<div class="setting-row"><div><b>${escapeHtml(p)}</b><small>Emulador predeterminado</small></div><select class="select-control focusable" data-focusable data-default-emulator data-platform="${escapeHtml(p)}"><option value="">Automático</option>${state.emulators.filter(e=>e.platform===p).map(e=>`<option value="${e.id}" ${defaults[p]===e.id?'selected':''}>${escapeHtml(e.name)}</option>`).join('')}</select></div>`).join('');
  $('#settingsContent').innerHTML=`<div class="settings-grid">
  <article class="settings-card settings-wide setup-callout"><div class="setup-callout-copy"><p class="eyebrow">¿NO SABES POR DÓNDE EMPEZAR?</p><h2>Asistente de configuración</h2><p>Te guía para añadir juegos de PC, ROMs, carpetas completas, Steam y emuladores.</p></div><button class="primary-button focusable" data-focusable data-action="setup-wizard">⚡ Configurar ORBIT</button></article>
  <article class="settings-card settings-wide"><div class="card-heading"><div><p class="eyebrow">TEMAS</p><h2>Aspecto visual</h2><p class="muted">Todos los temas funcionan con cualquiera de los modos de interfaz.</p></div></div><div class="theme-grid">${themeCards(s.theme||'dark')}</div><div class="setting-row"><div><b>Color principal</b><small>Puedes modificar el color del tema elegido.</small></div><input id="accentPicker" class="focusable color-input" data-focusable type="color" value="${escapeHtml(s.accent||THEME_DEFS[s.theme]?.accent||'#65f4c5')}"></div></article>
  <article class="settings-card settings-wide"><div class="card-heading"><div><p class="eyebrow">DISTRIBUCIÓN</p><h2>Modo de interfaz</h2><p class="muted">Cambiar un modo recoloca la navegación, tarjetas y zonas principales sin cambiar tu tema.</p></div></div><div class="mode-grid">${modeCards(s.interface_mode||'classic')}</div></article>
  <article class="settings-card"><div class="card-heading"><div><p class="eyebrow">PANTALLA</p><h2>Experiencia</h2></div></div><div class="setting-row"><div><b>Escala UI</b><small>Amplía o reduce todos los elementos. Útil en TV.</small></div><input id="uiScale" class="focusable range" data-focusable type="range" min="0.8" max="1.4" step="0.05" value="${Number(s.ui_scale||1)}"></div><div class="setting-row"><div><b>Reducir animaciones</b></div><button class="toggle focusable" data-focusable data-setting-toggle="reduce_motion" aria-pressed="${!!s.reduce_motion}"><span></span></button></div><div class="setting-row"><div><b>Iniciar en pantalla completa</b></div><button class="toggle focusable" data-focusable data-setting-toggle="start_fullscreen" aria-pressed="${s.start_fullscreen!==false}"><span></span></button></div></article>
  <article class="settings-card"><div class="card-heading"><div><p class="eyebrow">PERFIL</p><h2>Usuario y mando</h2></div><div class="button-row compact"><button class="secondary-button focusable" data-focusable data-action="profile-manager">Gestionar perfiles</button><button class="secondary-button focusable" data-focusable data-action="add-profile">＋ Perfil</button></div></div><div class="setting-row"><div><b>Perfil activo</b></div><select id="profileSelect" class="select-control focusable" data-focusable>${profileOptions()}</select></div><div class="setting-row"><div><b>Deadzone del mando</b><small>Cuánto debes mover el stick para navegar.</small></div><input id="controllerDeadzone" class="focusable range" data-focusable type="range" min="0.2" max="0.9" step="0.05" value="${Number(cp.deadzone||0.55)}"></div><div class="setting-row"><div><b>Botones del mando</b></div><button class="secondary-button focusable" data-focusable data-action="controller-mapping">Configurar</button></div></article>
  <article class="settings-card"><div class="card-heading"><div><p class="eyebrow">BIBLIOTECA</p><h2>Carpetas</h2></div><button class="secondary-button focusable" data-focusable data-action="add-folder">＋ Carpeta</button></div><div class="list-stack">${folders}</div></article>
  <article class="settings-card"><div class="card-heading"><div><p class="eyebrow">PARTIDAS</p><h2>Backups automáticos</h2></div></div><div class="setting-row"><div><b>Antes de jugar</b></div><button class="toggle focusable" data-focusable data-save-toggle="auto_backup_before_launch" aria-pressed="${!!s.saves?.auto_backup_before_launch}"><span></span></button></div><div class="setting-row"><div><b>Al cerrar el juego</b></div><button class="toggle focusable" data-focusable data-save-toggle="auto_backup_after_exit" aria-pressed="${!!s.saves?.auto_backup_after_exit}"><span></span></button></div></article>
  <article class="settings-card settings-wide"><div class="card-heading"><div><p class="eyebrow">EMULACIÓN</p><h2>Emuladores</h2></div><button class="secondary-button focusable" data-focusable data-action="add-emulator">＋ Emulador</button></div><div class="list-stack">${emulatorRows}</div>${defaultRows?`<div class="subsettings"><h3>Predeterminados por plataforma</h3>${defaultRows}</div>`:''}</article>
  <article class="settings-card"><div class="card-heading"><div><p class="eyebrow">IMPORTAR</p><h2>Bibliotecas existentes</h2></div></div><div class="button-column"><button class="secondary-button focusable" data-focusable data-action="import-steam">Importar Steam</button><button class="secondary-button focusable" data-focusable data-action="import-folder">Importar accesos directos / EXE</button></div></article>
  <article class="settings-card"><div class="card-heading"><div><p class="eyebrow">ALMACENAMIENTO</p><h2>Uso del USB</h2></div><button class="secondary-button focusable" data-focusable data-action="storage">Calcular</button></div><div id="storageBreakdown">${state.storage?storageMarkup(state.storage):'<p class="muted">Se calcula solo cuando lo pides para no ralentizar el arranque.</p>'}</div></article>
  <article class="settings-card"><div class="card-heading"><div><p class="eyebrow">ESTADO</p><h2>¿Está listo mi ORBIT?</h2></div></div><p class="muted">Comprueba biblioteca, emuladores, firmware/keys, rutas, partidas y portabilidad.</p><button class="primary-button focusable" data-focusable data-action="readiness">Comprobar todo</button></article>
  <article class="settings-card"><div class="card-heading"><div><p class="eyebrow">ORBIT AI</p><h2>Offline + modelo local</h2></div></div><p class="muted">El asistente integrado funciona sin Internet. Si configuras un LLM local, ORBIT lo usa y vuelve automáticamente al modo offline si no responde.</p><div class="setting-row"><div><b>Usar modelo local</b></div><button class="toggle focusable" data-focusable data-ai-toggle="local_model" aria-pressed="${!!s.ai?.local_model?.enabled}"><span></span></button></div><div class="field"><label>Modelo local</label><input id="aiLocalModel" class="focusable" data-focusable value="${escapeHtml(s.ai?.local_model?.model||'')}" placeholder="Ej.: llama3.2"></div><div class="field"><label>Endpoint local</label><input id="aiLocalEndpoint" class="focusable" data-focusable value="${escapeHtml(s.ai?.local_model?.endpoint||'http://127.0.0.1:11434')}" placeholder="http://127.0.0.1:11434"></div><div class="setting-row"><div><b>Búsqueda online opcional</b><small>Solo se usa si la activas y la petición solicita Internet/web.</small></div><button class="toggle focusable" data-focusable data-ai-toggle="online_search" aria-pressed="${!!s.ai?.online_search?.enabled}"><span></span></button></div><button class="secondary-button focusable" data-focusable data-action="orbit-ai">Abrir ORBIT AI</button></article>
  <article class="settings-card"><div class="card-heading"><div><p class="eyebrow">ORBIT PACK</p><h2>Importar / Exportar</h2></div></div><p class="muted">Transfiere juegos, emuladores, configuración, partidas, carátulas o el perfil completo. Las importaciones se verifican con SHA-256 y crean recuperación antes de modificar datos.</p><div class="button-column"><button class="secondary-button focusable" data-focusable data-action="orbitpack-export">Exportar .orbitpack</button><button class="secondary-button focusable" data-focusable data-action="orbitpack-import">Importar .orbitpack</button></div></article>
  <article class="settings-card settings-wide"><div class="card-heading"><div><p class="eyebrow">ORGANIZACIÓN</p><h2>Carpetas automáticas por consola</h2></div><button class="secondary-button focusable" data-focusable data-action="organization">Configurar</button></div><p class="muted">Los ORBIT Pack importados usan las carpetas de este perfil, no las del equipo que creó el paquete.</p></article>
  <article class="settings-card settings-wide"><div class="card-heading"><div><p class="eyebrow">TEMAS PERSONALIZADOS</p><h2>Creador visual</h2></div><button class="secondary-button focusable" data-focusable data-action="theme-editor">＋ Crear tema</button></div><p class="muted">Tamaño, forma, separación, sombras, animación y colores con previsualización. Sin introducir píxeles.</p></article>
  <article class="settings-card settings-wide"><div class="card-heading"><div><p class="eyebrow">CARÁTULAS ONLINE</p><h2>SteamGridDB opcional</h2></div><span class="status-badge ${s.cover_search?.api_key_configured?'ok':'warning'}">${s.cover_search?.api_key_configured?'Clave guardada':'Sin clave'}</span></div><div class="field"><label>Clave API personal</label><input id="steamGridKey" class="focusable" data-focusable type="password" autocomplete="off" value="" placeholder="${s.cover_search?.api_key_configured?'Escribe una nueva clave para sustituirla':'Introduce tu clave'}"></div><p class="muted">La clave se guarda fuera de settings.json y nunca se incluye en ORBIT Pack ni puntos de recuperación. PNG, JPG/JPEG, WEBP, GIF, AVIF, BMP e ICO están admitidos. TIFF se convierte a PNG cuando hay un decodificador disponible.</p>${s.cover_search?.api_key_configured?'<button class="secondary-button focusable" data-focusable data-action="steamgrid-clear">Eliminar clave guardada</button>':''}</article>
  <article class="settings-card"><div class="card-heading"><div><p class="eyebrow">ORBIT</p><h2>Acerca de</h2></div></div><div class="setting-row"><div><b>Versión instalada</b><small>Versión del launcher portable.</small></div><span class="status-badge">v${escapeHtml(state.version||'0.6.2')}</span></div></article>
  <article class="settings-card settings-wide"><div class="card-heading"><div><p class="eyebrow">INTEGRACIONES</p><h2>Preparado para ampliar</h2></div></div><div class="integration-grid"><div class="integration-item"><b>RetroAchievements</b><span>Arquitectura preparada; requiere cuenta/API y soporte por emulador.</span></div><div class="integration-item"><b>Discord Rich Presence</b><span>Preparado, desactivado por defecto para mantener portabilidad.</span></div><div class="integration-item"><b>Actualizador online</b><span>Preparado para un manifiesto firmado; no se activa sin una fuente segura.</span></div><div class="integration-item"><b>Plugins</b><span>La carpeta plugins está disponible; el código externo no se ejecuta automáticamente.</span></div></div></article>
  </div>`;
}
function storageMarkup(s){return `<div class="storage-total"><b>${formatBytes(s.free)} libres</b><span>de ${formatBytes(s.total)}</span></div><div class="storage-bars">${Object.entries(s.categories||{}).sort((a,b)=>b[1]-a[1]).map(([n,v])=>`<div><span>${escapeHtml(n)}</span><b>${formatBytes(v)}</b></div>`).join('')}</div>`;}
function renderSystem(system){const storage=system.storage||{},items=[['Sistema',system.os],['Arquitectura',system.architecture],['CPU',system.cpu||`${system.cpu_cores||'?'} núcleos`],['Núcleos',system.cpu_cores],['GPU',system.gpu],['RAM',system.ram_bytes?formatBytes(system.ram_bytes):'No detectada'],['Raíz ORBIT',system.launcher_root],['Espacio libre',storage.free?formatBytes(storage.free):'—'],['Resolución',`${screen.width} × ${screen.height}`],['Python',system.python]];$('#systemInfo').innerHTML=items.map(([l,v])=>`<div class="system-item"><small>${escapeHtml(l)}</small><b>${escapeHtml(v??'—')}</b></div>`).join('');if(storage.free)$('#storageHint').textContent=`${formatBytes(storage.free)} libres`;}
async function renderDiagnostics(refresh=false){if(refresh){const body=await api('/api/diagnostics');state.system=body.system;renderSystem(body.system);$('#diagnosticList').innerHTML=body.items.map(i=>`<div class="list-item"><div class="list-item-main"><b>${escapeHtml(i.name)}</b><small>${escapeHtml(i.detail)}</small></div><span class="status-badge ${escapeHtml(i.status)}">${i.status==='ok'?'Correcto':i.status==='warning'?'Revisar':'Error'}</span></div>`).join('');}else renderSystem(state.system||{});}

function applyTheme(){
  const requested=state.settings.theme||'dark';
  const custom=(state.customThemes||[]).find(t=>t.id===requested);
  const theme=custom?String(custom.base||'dark'):(THEME_DEFS[requested]?requested:'dark');
  const mode=MODE_DEFS[state.settings.interface_mode]?state.settings.interface_mode:'classic';
  for(const id of Object.keys(THEME_DEFS))document.body.classList.remove(`theme-${id}`);
  for(const id of Object.keys(MODE_DEFS))document.body.classList.remove(`mode-${id}`);
  document.body.classList.add(`theme-${theme}`,`mode-${mode}`);
  document.body.classList.toggle('light',theme==='light');
  document.body.classList.toggle('oled',theme==='oled');
  document.body.classList.toggle('reduce-motion',!!state.settings.reduce_motion);
  document.body.classList.toggle('safe-mode',!!state.safeMode);
  const root=document.documentElement;
  // Always clear custom variables first so a custom theme cannot contaminate an official one.
  for(const key of ['--bg','--surface','--surface-2','--surface-3','--text','--muted','--accent','--accent-2','--radius','--shadow']) root.style.removeProperty(key);
  if(custom){
    root.style.setProperty('--bg',custom.background||'#0b0f14');
    root.style.setProperty('--surface',custom.panel||'#141b24');
    root.style.setProperty('--surface-2',custom.panel||'#141b24');
    root.style.setProperty('--surface-3',custom.panel||'#141b24');
    root.style.setProperty('--text',custom.text||'#f5f7fb');
    root.style.setProperty('--muted',custom.muted||'#9aa8b6');
    root.style.setProperty('--accent',custom.accent||'#65f4c5');
    root.style.setProperty('--accent-2',custom.accent2||'#7aa7ff');
    const radius={straight:'4px',soft:'14px',rounded:'24px','very-rounded':'34px'}[custom.shape]||'24px';
    root.style.setProperty('--radius',radius);
    const shadow={none:'none',soft:'0 12px 28px rgba(0,0,0,.18)',medium:'0 28px 70px rgba(0,0,0,.38)',strong:'0 36px 90px rgba(0,0,0,.55)'}[custom.shadow]||'0 28px 70px rgba(0,0,0,.38)';
    root.style.setProperty('--shadow',shadow);
    document.body.dataset.customSize=custom.size||'medium';
    document.body.dataset.customSpacing=custom.spacing||'normal';
    document.body.dataset.customAnimation=custom.animation||'smooth';
  }else{
    delete document.body.dataset.customSize;delete document.body.dataset.customSpacing;delete document.body.dataset.customAnimation;
    root.style.setProperty('--accent',state.settings.accent||THEME_DEFS[theme].accent);
  }
  root.style.setProperty('--ui-scale',String(state.settings.ui_scale||1));
}
function renderCurrent(){applyTheme();if(state.view==='home')renderHome();if(state.view==='library')renderLibrary();if(state.view==='collections')renderCollections();if(state.view==='saves')renderSaves();if(state.view==='stats')renderStats();if(state.view==='settings')renderSettings();if(state.view==='diagnostics')renderSystem(state.system||{});$('#activeSessionHint').textContent=state.activeSessions.length?`▶ ${state.activeSessions.length} juego activo`:'';updateFocusables();}
function setView(view){state.view=view;$$('.view').forEach(el=>el.classList.toggle('active',el.dataset.viewPanel===view));$$('.nav-item').forEach(el=>el.classList.toggle('active',el.dataset.view===view));const names={home:['TU CONSOLA PORTABLE','Inicio'],library:['TODOS TUS JUEGOS','Biblioteca'],collections:['A TU MANERA','Colecciones'],saves:['PROTEGE TU PROGRESO','Partidas'],stats:['TU ACTIVIDAD','Estadísticas'],settings:['PERSONALIZA ORBIT','Ajustes'],diagnostics:['COMPROBACIÓN DEL SISTEMA','Diagnóstico']};const [e,t]=names[view]||names.home;$('#viewEyebrow').textContent=e;$('#viewTitle').textContent=t;if(view==='diagnostics')renderDiagnostics(true).catch(showError);else if(view==='stats'){api('/api/history').then(b=>{state.history=b.history||[];renderStats();updateFocusables();}).catch(showError);renderCurrent();}else renderCurrent();}

function openModal(html,wide=false){$('#modal').classList.toggle('modal-wide',wide);$('#modal').innerHTML=html;$('#modalBackdrop').hidden=false;updateFocusables();const f=$('.modal [data-focusable]');if(f)focusElement(f);}
function closeModal(){$('#modalBackdrop').hidden=true;$('#modal').innerHTML='';$('#modal').classList.remove('modal-wide');updateFocusables();}
function browseField(kind,target){return api(`/api/dialog/${kind}`,{method:'POST',body:'{}'}).then(b=>{if(b.path){const el=$(`[name="${CSS.escape(target)}"]`,$('#modal'));if(el)el.value=b.path;}return b.path;});}

function detailModal(game){const em=emulatorById(game.emulator_id),bg=mediaUrl(game.background,game.background_version),logo=mediaUrl(game.logo,game.logo_version);openModal(`<div class="detail-shell" ${bg?`style="--detail-bg:url('${escapeHtml(bg)}')"`:''}><div class="detail-backdrop"></div><div class="modal-head detail-head"><div><p class="eyebrow">${escapeHtml(game.platform)}</p><h2>Detalles</h2></div><button class="icon-button focusable" data-focusable data-action="close-modal">×</button></div><div class="modal-body"><div class="game-detail-v2"><div class="detail-cover">${coverMarkup(game)}</div><div class="detail-info">${logo?`<img class="detail-logo" src="${escapeHtml(logo)}" alt="${escapeHtml(game.name)}">`:`<h2>${escapeHtml(game.name)}</h2>`}<p>${escapeHtml(game.description||'Sin descripción.')}</p><div class="tag-row">${(game.tags||[]).map(t=>`<span class="tag">${escapeHtml(t)}</span>`).join('')}</div><div class="detail-facts"><div class="detail-fact"><small>Tiempo jugado</small><b>${formatDuration(game.play_time_seconds)}</b></div><div class="detail-fact"><small>Última sesión</small><b>${formatDuration(game.last_session_seconds)}</b></div><div class="detail-fact"><small>Última vez</small><b>${formatDate(game.last_played)}</b></div><div class="detail-fact"><small>Estado</small><b>${game.status==='completed'?'Completado':game.status==='playing'?'Jugando':'Pendiente'}</b></div><div class="detail-fact"><small>Emulador</small><b>${escapeHtml(em?.name||(game.platform==='PC'?'Nativo':'Sin configurar'))}</b></div><div class="detail-fact"><small>Datos</small><b>${escapeHtml([game.year,game.genre,game.players&&`${game.players} jugador(es)`].filter(Boolean).join(' · ')||'—')}</b></div></div><div class="media-strip">${(game.screenshots||[]).map((x,i)=>`<div class="shot"><img src="${escapeHtml(mediaUrl(x))}"><button class="mini-remove focusable" data-focusable data-action="remove-media" data-id="${game.id}" data-kind="screenshot" data-index="${i}">×</button></div>`).join('')}</div></div></div></div><div class="modal-actions modal-actions-wrap"><button class="secondary-button focusable" data-focusable data-action="edit-game" data-id="${game.id}">✎ Editar</button><button class="secondary-button focusable" data-focusable data-action="media-menu" data-id="${game.id}">🖼 Imágenes</button>${game.save_path?`<button class="secondary-button focusable" data-focusable data-action="backups" data-id="${game.id}">☁ Partidas</button>`:''}<button class="secondary-button focusable" data-focusable data-action="favorite" data-id="${game.id}">${game.favorite?'★ Quitar favorito':'☆ Favorito'}</button>${!game.demo?`<button class="danger-button focusable" data-focusable data-action="remove-game" data-id="${game.id}">Quitar</button>`:''}${game.demo?'<button class="primary-button focusable" data-focusable data-action="add-game">＋ Añadir juego real</button>':game.available?`<button class="primary-button focusable" data-focusable data-action="launch" data-id="${game.id}">▶ Jugar</button>`:'<button class="primary-button" disabled>⚠ Revisa configuración</button>'}</div></div>`,true);}
function gameForm(game=null){const g=game||{};const emOpts=state.emulators.map(e=>`<option value="${e.id}" ${g.emulator_id===e.id?'selected':''}>${escapeHtml(e.name)} (${escapeHtml(e.platform)})</option>`).join('');openModal(`<form id="gameForm"><div class="modal-head"><div><p class="eyebrow">BIBLIOTECA</p><h2>${game?'Editar juego':'Añadir juego'}</h2></div><button type="button" class="icon-button focusable" data-focusable data-action="close-modal">×</button></div><div class="modal-body"><div class="form-grid"><div class="field"><label>Nombre</label><input class="focusable" data-focusable name="name" value="${escapeHtml(g.name||'')}"></div><div class="field"><label>Plataforma</label><input class="focusable" data-focusable name="platform" value="${escapeHtml(g.platform||'PC')}"></div><div class="field wide"><label>Ruta del juego / ROM</label><div class="path-input"><input class="focusable" data-focusable type="${pathInputType()}" autocomplete="off" name="path" value="${escapeHtml(g.path||'')}"><button type="button" class="secondary-button focusable" data-focusable data-browse="game" data-target="path">Examinar</button></div></div><div class="field wide"><label>Ejecutable</label><div class="path-input"><input class="focusable" data-focusable type="${pathInputType()}" autocomplete="off" name="executable" value="${escapeHtml(g.executable||'')}"><button type="button" class="secondary-button focusable" data-focusable data-browse="game" data-target="executable">Examinar</button></div></div><div class="field"><label>Emulador</label><select class="focusable" data-focusable name="emulator_id"><option value="">Ninguno / automático</option>${emOpts}</select></div><div class="field"><label>Estado</label><select class="focusable" data-focusable name="status"><option value="backlog" ${g.status==='backlog'?'selected':''}>Pendiente</option><option value="playing" ${g.status==='playing'?'selected':''}>Jugando</option><option value="completed" ${g.status==='completed'?'selected':''}>Completado</option></select></div><div class="field"><label>Género</label><input class="focusable" data-focusable name="genre" value="${escapeHtml(g.genre||'')}"></div><div class="field"><label>Año</label><input class="focusable" data-focusable name="year" value="${escapeHtml(g.year||'')}"></div><div class="field"><label>Desarrollador</label><input class="focusable" data-focusable name="developer" value="${escapeHtml(g.developer||'')}"></div><div class="field"><label>Región</label><input class="focusable" data-focusable name="region" value="${escapeHtml(g.region||'')}" placeholder="Europa / USA / Japón"></div><div class="field"><label>Revisión / edición</label><input class="focusable" data-focusable name="revision" value="${escapeHtml(g.revision||'')}" placeholder="Rev 1 / GOTY / Traducción"></div><div class="field"><label>Demanda de rendimiento</label><select class="focusable" data-focusable name="performance_demand"><option value="">Automática</option>${[1,2,3,4,5].map(n=>`<option value="${n}" ${Number(g.performance_demand)===n?'selected':''}>Nivel ${n}/5</option>`).join('')}</select></div><div class="field"><label>Jugadores</label><input class="focusable" data-focusable name="players" value="${escapeHtml(g.players||'')}"></div><div class="field wide"><label>Etiquetas (separadas por comas)</label><input class="focusable" data-focusable name="tags" value="${escapeHtml((g.tags||[]).join(', '))}"></div><div class="field wide"><label>Argumentos de lanzamiento (opcional)</label><input class="focusable" data-focusable name="arguments" value="${escapeHtml(g.arguments||'')}"></div><div class="field wide"><label>Ruta de partidas guardadas</label><div class="path-input"><input class="focusable" data-focusable type="${pathInputType()}" autocomplete="off" name="save_path" value="${escapeHtml(g.save_path||'')}"><button type="button" class="secondary-button focusable" data-focusable data-browse="folder" data-target="save_path">Carpeta</button><button type="button" class="secondary-button focusable" data-focusable data-browse="file" data-target="save_path">Archivo</button></div></div><div class="field wide"><label>Descripción</label><textarea class="focusable" data-focusable name="description" rows="3">${escapeHtml(g.description||'')}</textarea></div><div class="field wide"><label>Notas privadas</label><textarea class="focusable" data-focusable name="notes" rows="2">${escapeHtml(g.notes||'')}</textarea></div><label class="check-row field wide"><input type="checkbox" name="hidden" ${g.hidden?'checked':''}> Ocultar de la biblioteca principal</label></div></div><div class="modal-actions"><button type="button" class="secondary-button focusable" data-focusable data-action="metadata-guess" data-id="${g.id||''}" ${game?'':'disabled'}>Detectar nombre/carátula local</button><button type="button" class="secondary-button focusable" data-focusable data-action="close-modal">Cancelar</button><button class="primary-button focusable" data-focusable type="submit">Guardar</button></div></form>`,true);$('#gameForm').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),data=Object.fromEntries(fd);data.hidden=fd.get('hidden')==='on';try{if(game)await api(`/api/games/${game.id}/update`,{method:'POST',body:JSON.stringify(data)});else await api('/api/games',{method:'POST',body:JSON.stringify(data)});closeModal();toast('Juego guardado','success');await loadState();}catch(err){showError(err);}});}
function mediaMenu(game){openModal(`<div class="modal-head"><div><p class="eyebrow">IMÁGENES</p><h2>${escapeHtml(game.name)}</h2></div><button class="icon-button focusable" data-focusable data-action="close-modal">×</button></div><div class="modal-body"><div class="media-options"><button class="media-option focusable" data-focusable data-action="set-media" data-kind="cover" data-id="${game.id}"><b>Carátula</b><span>${game.cover?'Cambiar':'Añadir'} imagen vertical</span></button><button class="media-option focusable" data-focusable data-action="set-media" data-kind="background" data-id="${game.id}"><b>Fondo</b><span>${game.background?'Cambiar':'Añadir'} imagen panorámica</span></button><button class="media-option focusable" data-focusable data-action="set-media" data-kind="logo" data-id="${game.id}"><b>Logo</b><span>${game.logo?'Cambiar':'Añadir'} imagen transparente</span></button><button class="media-option focusable" data-focusable data-action="set-media" data-kind="screenshot" data-id="${game.id}"><b>Captura</b><span>Añadir a la galería</span></button></div><div class="button-row">${['cover','background','logo'].filter(k=>game[k]).map(k=>`<button class="danger-button focusable" data-focusable data-action="remove-media" data-kind="${k}" data-id="${game.id}">Quitar ${k}</button>`).join('')}</div></div>`);}
function addFolderModal(){openModal(`<form id="folderForm"><div class="modal-head"><div><p class="eyebrow">ESCANEO</p><h2>Añadir carpeta</h2></div><button type="button" class="icon-button focusable" data-focusable data-action="close-modal">×</button></div><div class="modal-body"><div class="form-grid"><div class="field wide"><label>Carpeta</label><div class="path-input"><input class="focusable" data-focusable name="path"><button type="button" class="secondary-button focusable" data-focusable data-browse="folder" data-target="path">Examinar</button></div></div><div class="field wide"><label>Plataforma</label><select class="focusable" data-focusable name="platform">${platformOptions('PC')}</select></div></div></div><div class="modal-actions"><button class="primary-button focusable" data-focusable>Guardar</button></div></form>`);$('#folderForm').addEventListener('submit',async e=>{e.preventDefault();try{await api('/api/game-folders',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeModal();await loadState();toast('Carpeta añadida','success');}catch(err){showError(err);}});}
function emulatorForm(em=null){const e=em||{};openModal(`<form id="emulatorForm"><div class="modal-head"><div><p class="eyebrow">EMULACIÓN</p><h2>${em?'Editar':'Añadir'} emulador</h2></div><button type="button" class="icon-button focusable" data-focusable data-action="close-modal">×</button></div><div class="modal-body"><div class="form-grid"><div class="field"><label>Nombre</label><input class="focusable" data-focusable name="name" value="${escapeHtml(e.name||'')}"></div><div class="field"><label>Plataforma</label><select class="focusable" data-focusable name="platform">${platformOptions(e.platform||'PlayStation 2')}</select></div><div class="field wide"><label>Ejecutable</label><div class="path-input"><input class="focusable" data-focusable type="${pathInputType()}" autocomplete="off" name="executable" value="${escapeHtml(e.executable||'')}"><button type="button" class="secondary-button focusable" data-focusable data-browse="file" data-target="executable">Examinar</button></div></div><div class="field wide"><label>Argumentos</label><input class="focusable" data-focusable name="arguments" value="${escapeHtml(e.arguments||'\"{rom}\"')}"><small>Usa {rom} donde deba ir la ROM.</small></div><div class="field wide"><label>Directorio de trabajo (opcional)</label><div class="path-input"><input class="focusable" data-focusable type="${pathInputType()}" autocomplete="off" name="working_directory" value="${escapeHtml(e.working_directory||'')}"><button type="button" class="secondary-button focusable" data-focusable data-browse="folder" data-target="working_directory">Examinar</button></div></div></div></div><div class="modal-actions"><button class="primary-button focusable" data-focusable>Guardar</button></div></form>`);$('#emulatorForm').addEventListener('submit',async ev=>{ev.preventDefault();try{const data=Object.fromEntries(new FormData(ev.currentTarget));if(em)await api(`/api/emulators/${em.id}/update`,{method:'POST',body:JSON.stringify(data)});else await api('/api/emulators',{method:'POST',body:JSON.stringify(data)});closeModal();await loadState();toast('Emulador guardado','success');}catch(err){showError(err);}});}
function controllerMappingModal(){const c=state.settings.controller||{},p=(c.profiles||[]).find(x=>x.id===c.active_profile)||(c.profiles||[])[0]||{id:'default',name:'Predeterminado',mapping:{}};const m=p.mapping||{};openModal(`<form id="controllerMapForm"><div class="modal-head"><div><p class="eyebrow">MANDO</p><h2>Mapeo del launcher</h2></div><button type="button" class="icon-button focusable" data-focusable data-action="close-modal">×</button></div><div class="modal-body"><p class="muted">Valores habituales Xbox: A=0, B=1, Y=3, Menu=9. Puedes cambiarlos si tu mando usa otros índices.</p><div class="form-grid"><div class="field"><label>Aceptar</label><input class="focusable" data-focusable type="number" min="0" max="31" name="accept" value="${Number(m.accept??0)}"></div><div class="field"><label>Atrás</label><input class="focusable" data-focusable type="number" min="0" max="31" name="back" value="${Number(m.back??1)}"></div><div class="field"><label>Menú</label><input class="focusable" data-focusable type="number" min="0" max="31" name="menu" value="${Number(m.menu??9)}"></div><div class="field"><label>Favorito</label><input class="focusable" data-focusable type="number" min="0" max="31" name="favorite" value="${Number(m.favorite??3)}"></div></div></div><div class="modal-actions"><button class="primary-button focusable" data-focusable>Guardar</button></div></form>`);$('#controllerMapForm').addEventListener('submit',async e=>{e.preventDefault();const fd=Object.fromEntries(new FormData(e.currentTarget));const controller=structuredClone(state.settings.controller||{}),profile=(controller.profiles||[]).find(x=>x.id===controller.active_profile)||(controller.profiles||[])[0];if(!profile)return showError(new Error('No hay perfil de mando activo.'));profile.mapping={accept:Number(fd.accept),back:Number(fd.back),menu:Number(fd.menu),favorite:Number(fd.favorite)};try{await saveSettings({controller});closeModal();toast('Mapeo guardado','success');}catch(err){showError(err);}});}


function setupWizard(){
  openModal(`<div class="modal-head"><div><p class="eyebrow">ASISTENTE ORBIT</p><h2>¿Qué quieres añadir?</h2></div><button class="icon-button focusable" data-focusable data-action="close-modal">×</button></div><div class="modal-body"><p class="wizard-intro">No necesitas saber programar ni editar archivos. Elige una opción y ORBIT te pedirá únicamente lo necesario.</p><div class="wizard-grid"><button class="wizard-card focusable" data-focusable data-action="setup-pc"><span>🖥️</span><b>Juego de PC</b><small>Selecciona el .exe del juego y listo.</small></button><button class="wizard-card focusable" data-focusable data-action="setup-rom"><span>🎮</span><b>Juego emulado / ROM</b><small>Elige la ROM, consola y emulador.</small></button><button class="wizard-card focusable" data-focusable data-action="setup-folder"><span>📁</span><b>Carpeta completa</b><small>ORBIT buscará todos los juegos de una plataforma.</small></button><button class="wizard-card focusable" data-focusable data-action="setup-emulator"><span>⚙️</span><b>Configurar emulador</b><small>Añade Dolphin, PCSX2, RetroArch u otro.</small></button><button class="wizard-card focusable" data-focusable data-action="setup-steam"><span>♨</span><b>Importar Steam</b><small>Busca instalaciones locales de Steam.</small></button><button class="wizard-card focusable" data-focusable data-action="setup-import-folder"><span>✨</span><b>Detectar juegos de PC</b><small>Busca .exe y accesos directos en una carpeta.</small></button></div><div class="wizard-tip"><b>Consejo:</b> para una consola emulada, configura primero su emulador y después añade la carpeta de ROMs. Así ORBIT los enlaza automáticamente.</div></div><div class="modal-actions"><button class="secondary-button focusable" data-focusable data-action="setup-finish">Cerrar asistente</button></div>`,true);
}
function quickPcModal(){
  openModal(`<form id="quickPcForm"><div class="modal-head"><div><p class="eyebrow">JUEGO DE PC</p><h2>Añadir en 2 pasos</h2></div><button type="button" class="icon-button focusable" data-focusable data-action="close-modal">×</button></div><div class="modal-body"><div class="step-banner"><span>1</span><div><b>Selecciona el ejecutable</b><small>Normalmente termina en .exe. ORBIT no moverá ni borrará ese archivo.</small></div></div><div class="field"><label>Ejecutable del juego</label><div class="path-input"><input class="focusable" data-focusable type="${pathInputType()}" autocomplete="off" name="executable" required placeholder="Selecciona el .exe"><button type="button" class="secondary-button focusable" data-focusable data-browse="game" data-target="executable">Examinar</button></div></div><div class="step-banner"><span>2</span><div><b>Nombre</b><small>Es opcional: si lo dejas vacío ORBIT usará el nombre del archivo.</small></div></div><div class="field"><label>Nombre del juego</label><input class="focusable" data-focusable name="name" placeholder="Opcional"></div></div><div class="modal-actions"><button type="button" class="secondary-button focusable" data-focusable data-action="setup-wizard">Atrás</button><button class="primary-button focusable" data-focusable>✓ Añadir juego</button></div></form>`);
  $('#quickPcForm').addEventListener('submit',async e=>{e.preventDefault();try{const data=Object.fromEntries(new FormData(e.currentTarget));data.platform='PC';await api('/api/games',{method:'POST',body:JSON.stringify(data)});closeModal();await loadState();toast('Juego de PC añadido','success');setView('library');}catch(err){showError(err);}});
}
function quickRomModal(){
  const emOpts=state.emulators.map(e=>`<option value="${e.id}">${escapeHtml(e.name)} — ${escapeHtml(e.platform)}</option>`).join('');
  openModal(`<form id="quickRomForm"><div class="modal-head"><div><p class="eyebrow">JUEGO EMULADO</p><h2>Añadir ROM</h2></div><button type="button" class="icon-button focusable" data-focusable data-action="close-modal">×</button></div><div class="modal-body"><div class="step-banner"><span>1</span><div><b>Selecciona la ROM</b><small>ISO, CHD, RVZ, ROM, etc. según la consola.</small></div></div><div class="field"><label>Archivo del juego</label><div class="path-input"><input class="focusable" data-focusable type="${pathInputType()}" autocomplete="off" name="path" required><button type="button" class="secondary-button focusable" data-focusable data-browse="game" data-target="path">Examinar</button></div></div><div class="form-grid wizard-fields"><div class="field"><label>Consola / plataforma</label><select id="quickRomPlatform" class="focusable" data-focusable name="platform">${platformOptions('PlayStation 2')}</select></div><div class="field"><label>Emulador</label><select id="quickRomEmulator" class="focusable" data-focusable name="emulator_id"><option value="">Automático / configurar después</option>${emOpts}</select></div><div class="field wide"><label>Nombre (opcional)</label><input class="focusable" data-focusable name="name" placeholder="ORBIT usará el nombre del archivo"></div></div>${state.emulators.length?'':'<div class="wizard-warning">⚠ Todavía no tienes emuladores. Puedes añadir la ROM ahora, pero necesitarás configurar uno antes de poder jugar.</div>'}</div><div class="modal-actions"><button type="button" class="secondary-button focusable" data-focusable data-action="setup-wizard">Atrás</button>${state.emulators.length?'':`<button type="button" class="secondary-button focusable" data-focusable data-action="setup-emulator">Configurar emulador</button>`}<button class="primary-button focusable" data-focusable>✓ Añadir ROM</button></div></form>`);
  $('#quickRomForm').addEventListener('submit',async e=>{e.preventDefault();try{const data=Object.fromEntries(new FormData(e.currentTarget));await api('/api/games',{method:'POST',body:JSON.stringify(data)});closeModal();await loadState();toast('Juego emulado añadido','success');setView('library');}catch(err){showError(err);}});
}

function collectionModal(collection=null){const selected=new Set(collection?.game_ids||[]);openModal(`<form id="collectionForm"><div class="modal-head"><div><p class="eyebrow">COLECCIÓN</p><h2>${collection?'Editar':'Nueva'} colección</h2></div><button type="button" class="icon-button focusable" data-focusable data-action="close-modal">×</button></div><div class="modal-body"><div class="field"><label>Nombre</label><input class="focusable" data-focusable name="name" value="${escapeHtml(collection?.name||'')}"></div><div class="collection-picker">${state.games.filter(g=>!g.demo).map(g=>`<label class="pick-game"><input type="checkbox" name="game_ids" value="${g.id}" ${selected.has(g.id)?'checked':''}>${coverMarkup(g)}<span>${escapeHtml(g.name)}</span></label>`).join('')}</div></div><div class="modal-actions"><button class="primary-button focusable" data-focusable>Guardar</button></div></form>`,true);$('#collectionForm').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),payload={id:collection?.id,name:fd.get('name'),game_ids:fd.getAll('game_ids')};try{await api('/api/collections',{method:'POST',body:JSON.stringify(payload)});closeModal();await loadState();toast('Colección guardada','success');}catch(err){showError(err);}});}
async function backupsModal(game){try{const body=await api(`/api/games/${game.id}/backups`);const backups=body.backups||[];openModal(`<div class="modal-head"><div><p class="eyebrow">BACKUPS</p><h2>${escapeHtml(game.name)}</h2></div><button class="icon-button focusable" data-focusable data-action="close-modal">×</button></div><div class="modal-body"><div class="list-stack">${backups.length?backups.map(b=>`<div class="list-item"><div class="list-item-main"><b>${formatDate(b.created_at)} · ${escapeHtml(b.reason||'manual')}</b><small>${formatBytes(b.size_bytes)}</small></div>${b.corrupt?'<span class="status-badge error">Dañado</span>':`<button class="secondary-button focusable" data-focusable data-action="restore" data-id="${game.id}" data-backup="${escapeHtml(b.backup_id)}">Restaurar</button>`}</div>`).join(''):'<div class="empty-state">Aún no hay backups.</div>'}</div></div><div class="modal-actions"><button class="primary-button focusable" data-focusable data-action="backup" data-id="${game.id}">Crear backup ahora</button></div>`);}catch(err){showError(err);}}
function importPreviewModal(items,title){openModal(`<div class="modal-head"><div><p class="eyebrow">IMPORTAR</p><h2>${escapeHtml(title)}</h2></div><button class="icon-button focusable" data-focusable data-action="close-modal">×</button></div><div class="modal-body"><p>${items.length} elementos encontrados.</p><div class="import-list">${items.slice(0,500).map((x,i)=>`<label class="import-row"><input type="checkbox" data-import-index="${i}" checked><span><b>${escapeHtml(x.name)}</b><small>${escapeHtml(displayPath(x.path||x.launch_uri||''))}</small></span></label>`).join('')||'<div class="empty-state">No se encontraron juegos.</div>'}</div></div><div class="modal-actions"><button class="primary-button focusable" data-focusable data-action="apply-import" ${items.length?'':'disabled'}>Importar seleccionados</button></div>`,true);$('#modal').dataset.importItems=JSON.stringify(items);}

async function saveSettings(patch){const b=await api('/api/settings',{method:'POST',body:JSON.stringify(patch),retryNetwork:true});state.settings=b.settings;applyTheme();renderCurrent();toast('Ajustes guardados','success');}
async function loadState(){const b=await api('/api/state');Object.assign(state,{games:b.games||[],emulators:b.emulators||[],emulatorSites:b.emulator_sites||[],emulatorPackages:b.emulator_packages||[],settings:b.settings||{},stats:b.stats||{},system:b.system||{},collections:b.collections||[],profiles:b.profiles||{},activeSessions:b.active_sessions||[],customThemes:b.custom_themes||[],safeMode:!!b.safe_mode,version:b.version||state.version||'0.6.2'});applyTheme();renderCurrent();}
async function scanLibrary(){try{toast('Actualizando biblioteca…');const b=await api('/api/scan',{method:'POST',body:'{}'});await loadState();toast(`Biblioteca actualizada: ${b.result.added} nuevos, ${b.result.missing} a revisar`,'success');}catch(err){showError(err);}}
async function launchGame(id){try{await api(`/api/games/${id}/launch`,{method:'POST',body:'{}'});toast('Juego iniciado','success');setTimeout(()=>loadState().catch(()=>{}),500);}catch(err){showError(err);}}



async function portableCheckModal(){
  try{const b=await api('/api/portable-check'),r=b.result;const blockers=(r.blockers||[]).map(x=>`<li class="danger-text">${escapeHtml(x)}</li>`).join(''),warnings=(r.warnings||[]).map(x=>`<li>${escapeHtml(x)}</li>`).join('');openModal(`<div class="modal-head"><div><p class="eyebrow">PORTABILIDAD</p><h2>${r.ready?'✓ ORBIT preparado':'Revisión necesaria'}</h2></div><button class="icon-button focusable" data-focusable data-action="close-modal">×</button></div><div class="modal-body"><div class="stats-row"><span>${r.games} juegos</span><span>${r.emulators} emuladores</span><span>${formatBytes(r.free_bytes)} libres</span></div>${blockers?`<h3>Bloqueos</h3><ul>${blockers}</ul>`:''}${warnings?`<h3>Avisos</h3><ul>${warnings}</ul>`:''}${!blockers&&!warnings?'<div class="info-banner"><div><b>Todo correcto</b><p>No se han encontrado dependencias evidentes que impidan usar este perfil en otro PC.</p></div></div>':''}</div><div class="modal-actions"><button class="primary-button focusable" data-focusable data-action="close-modal">Entendido</button></div>`,true);}catch(err){showError(err);}
}
async function duplicatesModal(){try{const b=await api('/api/duplicates'),groups=b.result.groups||[];openModal(`<div class="modal-head"><div><p class="eyebrow">BIBLIOTECA</p><h2>Duplicados</h2></div><button class="icon-button focusable" data-focusable data-action="close-modal">×</button></div><div class="modal-body">${groups.length?groups.map(g=>`<article class="list-item"><div class="list-item-main"><b>${escapeHtml(g.reason)}</b><small>${g.games.map(x=>`${escapeHtml(x.name)} · ${escapeHtml(x.platform)}`).join(' / ')}</small></div></article>`).join(''):'<div class="empty-state">No se han detectado duplicados evidentes.</div>'}<p class="muted">ORBIT no elimina nada automáticamente desde esta herramienta.</p></div>`,true);}catch(err){showError(err);}}
async function recoveryCenterModal(){try{const b=await api('/api/recovery'),items=b.items||[];openModal(`<div class="modal-head"><div><p class="eyebrow">RECUPERACIÓN</p><h2>Puntos de recuperación</h2></div><button class="icon-button focusable" data-focusable data-action="close-modal">×</button></div><div class="modal-body"><p class="muted">Guardan configuración y biblioteca, no duplican los archivos físicos de juegos.</p><div class="list-stack">${items.map(x=>`<div class="list-item"><div class="list-item-main"><b>${escapeHtml(x.filename)}</b><small>${formatBytes(x.size)} · ${formatDate(x.modified_at)}</small></div><button class="secondary-button focusable" data-focusable data-action="recovery-restore" data-path="${escapeHtml(x.path)}">Restaurar</button></div>`).join('')||'<div class="empty-state">Todavía no hay puntos de recuperación.</div>'}</div></div><div class="modal-actions"><button class="primary-button focusable" data-focusable data-action="recovery-create">Crear punto ahora</button></div>`,true);}catch(err){showError(err);}}

function orbitpackExportProgressModal(jobId){
  openModal(`<div class="modal-head"><div><p class="eyebrow">ORBIT PACK</p><h2>Exportando paquete…</h2></div><button type="button" class="icon-button focusable" data-focusable data-action="close-modal">×</button></div><div class="modal-body"><div class="export-progress-shell"><div class="export-progress-head"><b id="orbitExportPercent">0%</b><span id="orbitExportEta">Calculando…</span></div><div class="export-progress-track" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><div id="orbitExportBar" class="export-progress-fill"></div></div><p id="orbitExportPhase" class="muted">Preparando archivos…</p><div class="export-progress-stats"><span id="orbitExportBytes">0 B</span><span id="orbitExportCurrent"></span></div></div><p class="muted">La estimación se ajusta mientras ORBIT comprime los archivos. Puedes cerrar esta ventana: la exportación continuará.</p></div>`,true);
  (async()=>{
    try{
      while(true){
        const body=await api(`/api/orbitpack/export/progress?job_id=${encodeURIComponent(jobId)}`,{retryNetwork:true}),job=body.job||{};
        const pct=Math.max(0,Math.min(100,Math.round((Number(job.percent)||0)*100)));
        const bar=$('#orbitExportBar'),percent=$('#orbitExportPercent'),eta=$('#orbitExportEta'),phase=$('#orbitExportPhase'),bytes=$('#orbitExportBytes'),current=$('#orbitExportCurrent'),track=$('.export-progress-track');
        if(bar)bar.style.width=`${pct}%`;if(percent)percent.textContent=`${pct}%`;if(eta)eta.textContent=job.status==='done'?'Completado':formatEta(job.eta_seconds);if(track)track.setAttribute('aria-valuenow',String(pct));
        if(phase)phase.textContent=job.phase==='preparing'?'Preparando archivos…':job.phase==='manifest'?'Verificando manifiesto SHA-256…':job.phase==='done'?'Exportación completada.':'Comprimiendo y verificando archivos…';
        if(bytes){const total=Number(job.total_bytes)||0,done=Number(job.processed_bytes)||0;bytes.textContent=total?`${formatBytes(done)} / ${formatBytes(total)}`:formatBytes(done);}
        if(current)current.textContent=job.current?String(job.current).split('/').pop():'';
        if(job.status==='error')throw new Error(job.error||'No se pudo exportar el ORBIT Pack.');
        if(job.status==='done'){
          const r=job.result||{};toast(`ORBIT Pack creado: ${r.filename||'paquete'}`,'success');
          if($('#orbitExportBar'))openModal(`<div class="modal-head"><div><p class="eyebrow">EXPORTADO</p><h2>${escapeHtml(r.filename||'ORBIT Pack')}</h2></div><button class="icon-button focusable" data-focusable data-action="close-modal">×</button></div><div class="modal-body"><div class="stats-row"><span>${r.games||0} juegos</span><span>${r.rom_files||0} ROMs incluidas</span><span>${r.emulators||0} emuladores</span><span>${formatBytes(r.size||0)}</span></div><div class="export-complete">✓ 100% · Integridad SHA-256 generada</div><p class="muted">${escapeHtml(displayPath(r.path||''))}</p></div><div class="modal-actions"><button class="primary-button focusable" data-focusable data-action="close-modal">Entendido</button></div>`,true);
          return;
        }
        await wait(250);
      }
    }catch(err){showError(err);const phase=$('#orbitExportPhase');if(phase)phase.textContent=`Error: ${err?.message||String(err)}`;}
  })();
}

function orbitpackExportModal(){
  const real=state.games.filter(g=>!g.demo);
  const gameRows=real.map(g=>`<label class="check-row orbitpack-game-row"><input type="checkbox" name="game_id" value="${escapeHtml(g.id)}" checked> <span><b>${escapeHtml(g.name)}</b><small>${escapeHtml(g.platform||'')}</small></span></label>`).join('');
  openModal(`<form id="orbitpackExportForm"><div class="modal-head"><div><p class="eyebrow">ORBIT PACK</p><h2>Exportar .orbitpack</h2></div><button type="button" class="icon-button focusable" data-focusable data-action="close-modal">×</button></div><div class="modal-body"><p class="muted">Elige exactamente qué quieres incluir. La configuración se sanea y nunca contiene el token de SteamGridDB.</p><div class="field"><label>Nombre del paquete</label><input class="focusable" data-focusable name="name" maxlength="80" placeholder="Mi ORBIT"></div><label class="check-row"><input type="checkbox" name="include_games" checked> <span>🎮 Juegos y metadatos</span></label><label class="check-row warning"><input type="checkbox" name="include_game_files" checked> <span>Archivos físicos de los juegos / ROMs seleccionados (necesarios para transferirlos)</span></label><label class="check-row"><input type="checkbox" name="include_emulators" checked> <span>🕹️ Emuladores</span></label><label class="check-row"><input type="checkbox" name="include_configuration"> <span>⚙️ Configuración</span></label><label class="check-row"><input type="checkbox" name="include_saves"> <span>💾 Partidas / guardados de los juegos seleccionados</span></label><label class="check-row"><input type="checkbox" name="include_media" checked> <span>🖼️ Carátulas y multimedia de los juegos seleccionados</span></label><label class="check-row"><input type="checkbox" name="include_other"> <span>📁 Otros datos compatibles</span></label><label class="check-row"><input type="checkbox" name="full_profile"> <span>👤 <b>Perfil completo</b> (todos los componentes y todos los juegos)</span></label><div class="orbitpack-game-selector"><div class="card-heading"><div><p class="eyebrow">JUEGOS</p><h3>Selecciona qué juegos viajarán</h3></div><span id="orbitpackGameCount" class="status-badge ok">${real.length}/${real.length}</span></div><div class="button-row"><button type="button" id="orbitpackSelectAll" class="secondary-button focusable" data-focusable>Seleccionar todo</button><button type="button" id="orbitpackSelectNone" class="secondary-button focusable" data-focusable>Deseleccionar todo</button></div><div class="orbitpack-game-list">${gameRows||'<div class="empty-state">No hay juegos reales en este perfil.</div>'}</div></div><div class="info-banner small"><div><b>Portable y verificable</b><p>Al exportar, Windows te preguntará dónde guardar el archivo. Verás progreso real, tamaño procesado y tiempo aproximado restante.</p></div></div></div><div class="modal-actions"><button type="button" class="secondary-button focusable" data-focusable data-action="close-modal">Cancelar</button><button class="primary-button focusable" data-focusable>Exportar paquete…</button></div></form>`,true);
  const form=$('#orbitpackExportForm'),gameBoxes=()=>$$('input[name="game_id"]',form);
  const componentNames=['include_games','include_game_files','include_emulators','include_configuration','include_saves','include_media','include_other'];
  const updateCount=()=>{const boxes=gameBoxes(),selected=boxes.filter(x=>x.checked).length,count=$('#orbitpackGameCount');if(count)count.textContent=`${selected}/${boxes.length}`;};
  const leaveFullProfile=()=>{if(form.elements.full_profile.checked)form.elements.full_profile.checked=false;};
  $('#orbitpackSelectAll')?.addEventListener('click',()=>{gameBoxes().forEach(x=>x.checked=true);updateCount();});
  $('#orbitpackSelectNone')?.addEventListener('click',()=>{gameBoxes().forEach(x=>x.checked=false);leaveFullProfile();updateCount();});
  gameBoxes().forEach(x=>x.addEventListener('change',()=>{if(!x.checked)leaveFullProfile();updateCount();}));
  form.elements.include_game_files.addEventListener('change',()=>{if(form.elements.include_game_files.checked)form.elements.include_games.checked=true;else leaveFullProfile();});
  form.elements.include_games.addEventListener('change',()=>{if(!form.elements.include_games.checked){form.elements.include_game_files.checked=false;leaveFullProfile();}else{form.elements.include_game_files.checked=true;}});
  componentNames.filter(n=>!['include_games','include_game_files'].includes(n)).forEach(n=>form.elements[n].addEventListener('change',()=>{if(!form.elements[n].checked)leaveFullProfile();}));
  form.elements.full_profile.addEventListener('change',()=>{if(form.elements.full_profile.checked){componentNames.forEach(n=>form.elements[n].checked=true);gameBoxes().forEach(x=>x.checked=true);updateCount();}});
  form.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);const payload={name:String(fd.get('name')||''),include_games:fd.has('include_games'),include_game_files:fd.has('include_game_files'),include_emulators:fd.has('include_emulators'),include_configuration:fd.has('include_configuration'),include_saves:fd.has('include_saves'),include_media:fd.has('include_media'),include_other:fd.has('include_other'),full_profile:fd.has('full_profile')};if(!Object.entries(payload).some(([k,v])=>k!=='name'&&v===true))return toast('Selecciona al menos un contenido para exportar.','warning');const gameScoped=payload.include_games||payload.include_game_files||payload.include_saves||payload.include_media;if(gameScoped&&!payload.full_profile){payload.game_ids=fd.getAll('game_id').map(String);if(!payload.game_ids.length)return toast('Selecciona al menos un juego para los contenidos de juegos/carátulas/partidas.','warning');}try{const picker=await api('/api/dialog/save_orbitpack',{method:'POST',body:JSON.stringify({suggested_name:payload.name||'ORBIT-Pack'})});if(!picker.path)return;payload.destination=picker.path;const started=await api('/api/orbitpack/export/start',{method:'POST',body:JSON.stringify(payload)});closeModal();orbitpackExportProgressModal(started.job_id);}catch(err){showError(err);}});
}

function orbitpackImportProgressModal(jobId){
  openModal(`<div class="modal-head"><div><p class="eyebrow">ORBIT PACK</p><h2>Importando paquete…</h2></div><button type="button" class="icon-button focusable" data-focusable data-action="close-modal">×</button></div><div class="modal-body"><div class="export-progress-shell"><div class="export-progress-head"><b id="orbitImportPercent">0%</b><span id="orbitImportEta">Calculando…</span></div><div class="export-progress-track" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><div id="orbitImportBar" class="export-progress-fill"></div></div><p id="orbitImportPhase" class="muted">Verificando la integridad del paquete…</p><div class="export-progress-stats"><span id="orbitImportBytes">Preparando…</span><span id="orbitImportCurrent"></span></div></div><p class="muted">El porcentaje y el tiempo se actualizan con el trabajo del backend. Puedes cerrar esta ventana; la importación continuará.</p></div>`,true);
  (async()=>{
    try{
      while(true){
        const body=await api(`/api/orbitpack/import/progress?job_id=${encodeURIComponent(jobId)}`,{retryNetwork:true}),job=body.job||{};
        const pct=Math.max(0,Math.min(100,Math.round((Number(job.percent)||0)*100)));
        const bar=$('#orbitImportBar'),percent=$('#orbitImportPercent'),eta=$('#orbitImportEta'),phase=$('#orbitImportPhase'),bytes=$('#orbitImportBytes'),current=$('#orbitImportCurrent'),track=bar?.closest('[role="progressbar"]');
        if(bar)bar.style.width=`${pct}%`;
        if(percent)percent.textContent=`${pct}%`;
        if(eta)eta.textContent=job.status==='done'?'Completado':formatEta(job.eta_seconds);
        if(track)track.setAttribute('aria-valuenow',String(pct));
        if(phase)phase.textContent=({verifying:'Comprobando SHA-256…',extracting:'Extrayendo el paquete…',importing:'Colocando el contenido en tus carpetas automáticas…',done:'Importación completada.'})[job.phase]||'Preparando importación…';
        if(bytes){const done=Number(job.processed_bytes)||0,total=Number(job.total_bytes)||0;bytes.textContent=total?`${formatBytes(done)} procesados`:'Preparando archivos…';}
        if(current)current.textContent=job.current?String(job.current).split('/').pop():'';
        if(job.status==='error')throw new Error(job.error||'No se pudo importar el paquete. Se ha recuperado el estado previo.');
        if(job.status==='done'){
          const r=job.result||{};
          await loadState();
          toast(`Importados: ${r.added||0} juegos · ${r.roms||0} ROMs · ${r.saves||0} partidas · ${r.media||0} imágenes`,'success');
          if($('#orbitImportBar'))openModal(`<div class="modal-head"><div><p class="eyebrow">IMPORTACIÓN COMPLETADA</p><h2>ORBIT Pack importado</h2></div><button type="button" class="icon-button focusable" data-focusable data-action="close-modal">×</button></div><div class="modal-body"><div class="export-complete">✓ 100% · Importación terminada</div><p>${r.added||0} juegos añadidos · ${r.roms||0} ROMs copiadas · ${r.skipped||0} duplicados omitidos · ${r.media||0} imágenes · ${r.saves||0} partidas.</p>${r.metadata_only?`<p class="muted">${r.metadata_only} juegos se añadieron a la biblioteca sin ROM física: vincula su archivo para poder ejecutarlos.</p>`:''}${r.save_conflicts?`<p class="muted">${r.save_conflicts} carpetas de partidas ya existían. Las importadas se guardaron aparte para no sobrescribir tus partidas.</p><p class="muted">Rutas importadas: ${(r.save_locations||[]).map(escapeHtml).join(' · ')}</p>`:''}</div><div class="modal-actions"><button class="primary-button focusable" data-focusable data-action="close-modal">Entendido</button></div>`,true);
          return;
        }
        await wait(250);
      }
    }catch(err){showError(err);const phase=$('#orbitImportPhase');if(phase)phase.textContent=`Error: ${err?.message||String(err)}`;}
  })();
}

async function orbitpackInspectAndChoose(path){
  const status=$('#orbitpackChooseStatus');if(status)status.textContent='Verificando SHA-256 del archivo…';
  try{
    const b=await api('/api/orbitpack/inspect',{method:'POST',body:JSON.stringify({path})}),r=b.result||{},available=r.components||{};
    const labels={games:'🎮 Juegos',emulators:'🕹️ Emuladores',configuration:'⚙️ Configuración',saves:'💾 Partidas/guardados',media:'🖼️ Carátulas y multimedia',other:'📁 Otros datos del perfil'};
    const choices=Object.entries(labels).filter(([key])=>available[key]).map(([key,label])=>`<label class="check-row"><input type="checkbox" name="component" value="${key}" checked> <span>${label}</span></label>`).join('');
    const plats=Object.entries(r.platforms||{}).map(([p,n])=>`${escapeHtml(p)}: ${n}`).join(' · ');
    const folders=Object.entries(r.destinations||{}).map(([platform,dest])=>`<small>${escapeHtml(platform)} → ${escapeHtml(dest)}</small>`).join('<br>');
    openModal(`<form id="orbitpackImportForm"><div class="modal-head"><div><p class="eyebrow">IMPORTAR</p><h2>ORBIT Pack verificado</h2></div><button type="button" class="icon-button focusable" data-focusable data-action="close-modal">×</button></div><div class="modal-body"><div class="stats-row"><span>${r.games||0} juegos</span><span>${r.rom_files||0} ROMs incluidas</span><span>${r.emulators||0} emuladores</span><span>${formatBytes(r.size||0)}</span><span>${r.duplicates||0} posibles duplicados</span></div><p>${plats||'Sin plataformas de juego'}</p><div class="info-banner small success"><div><b>Integridad SHA-256 correcta</b><p>Se creará un punto de recuperación antes de importar. Se utilizarán tus carpetas automáticas existentes.</p></div></div>${r.rom_missing?`<div class="info-banner small warning"><div><b>Atención: faltan ROMs en este paquete</b><p>Incluye ${r.rom_files||0} archivos físicos; faltan ${r.rom_missing} ROMs. Los juegos sin ROM solo se pueden registrar o vincular a un archivo que ya exista; para transferirlos debes volver a exportarlos desde el ORBIT original marcando archivos físicos.</p></div></div>`:''}${folders?`<div class="info-banner small"><div><b>Destinos actuales</b><p>${folders}</p></div></div>`:''}<h3>Selecciona exactamente qué importar</h3>${choices||'<p class="muted">El paquete no contiene componentes importables.</p>'}<div class="button-row"><button type="button" class="secondary-button focusable" data-focusable id="orbitImportAll">Seleccionar todo</button><button type="button" class="secondary-button focusable" data-focusable id="orbitImportNone">Deseleccionar todo</button></div><div class="field"><label>Perfil receptor</label><select class="focusable" data-focusable name="profile_strategy"><option value="merge-active">Fusionar con el perfil activo sin borrar datos existentes</option><option value="new-profile">Crear un perfil nuevo</option></select></div><div class="field"><label>Conflictos de juegos</label><select class="focusable" data-focusable name="conflict"><option value="skip">Conservar existente y omitir duplicado</option><option value="replace-metadata">Actualizar únicamente metadatos</option><option value="keep-both">Mantener ambos</option></select></div><div class="field"><label>Conflictos de configuración</label><select class="focusable" data-focusable name="config_conflict"><option value="keep-existing">Conservar ajustes existentes</option><option value="import-preferred">Preferir ajustes importados</option></select></div><input type="hidden" name="path" value="${escapeHtml(path)}"></div><div class="modal-actions"><button type="button" class="secondary-button focusable" data-focusable data-action="close-modal">Cancelar</button><button class="primary-button focusable" data-focusable>Importar seleccionados</button></div></form>`,true);
    const form=$('#orbitpackImportForm');
    $('#orbitImportAll')?.addEventListener('click',()=>$$('input[name="component"]',form).forEach(box=>box.checked=true));
    $('#orbitImportNone')?.addEventListener('click',()=>$$('input[name="component"]',form).forEach(box=>box.checked=false));
    form.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(form),components=fd.getAll('component');if(!components.length)return toast('Selecciona al menos un componente.','warning');const payload={path:String(fd.get('path')||''),conflict:String(fd.get('conflict')||'skip'),profile_strategy:String(fd.get('profile_strategy')||'merge-active'),config_conflict:String(fd.get('config_conflict')||'keep-existing'),components};try{const started=await api('/api/orbitpack/import/start',{method:'POST',body:JSON.stringify(payload)});closeModal();orbitpackImportProgressModal(started.job_id);}catch(err){showError(err);}});
  }catch(err){if(status)status.textContent=`Error: ${err?.message||String(err)}`;showError(err);}
}

function orbitpackImportStart(){
  // Always open an ORBIT dialog first: a failed/hidden native Windows picker
  // must never make the Import button appear to do nothing.
  openModal(`<div class="modal-head"><div><p class="eyebrow">ORBIT PACK</p><h2>Elegir archivo .orbitpack</h2></div><button type="button" class="icon-button focusable" data-focusable data-action="close-modal">×</button></div><div class="modal-body"><p class="muted">Elige el paquete que quieres importar. Puedes usar el explorador integrado del navegador o el selector nativo de Windows.</p><div class="field"><label>Seleccionar archivo</label><input type="file" class="focusable" data-focusable id="orbitpackBrowserFile" accept=".orbitpack"></div><button type="button" class="secondary-button focusable" data-focusable id="orbitpackWindowsFile">Examinar con Windows…</button><div class="field"><label>O pega la ruta completa de un archivo existente</label><input type="text" class="focusable" data-focusable id="orbitpackLocalPath" placeholder="C:\\...\\copia.orbitpack"></div><p id="orbitpackChooseStatus" class="muted" role="status">Esperando archivo…</p></div><div class="modal-actions"><button type="button" class="secondary-button focusable" data-focusable data-action="close-modal">Cancelar</button><button type="button" class="primary-button focusable" data-focusable id="orbitpackInspectPath">Comprobar archivo</button></div>`,true);
  $('#orbitpackWindowsFile')?.addEventListener('click',async()=>{try{const d=await api('/api/dialog/orbitpack',{method:'POST',body:'{}'});if(d.path)await orbitpackInspectAndChoose(d.path);}catch(err){const status=$('#orbitpackChooseStatus');if(status)status.textContent=`El selector nativo no está disponible: ${err?.message||String(err)}. Puedes utilizar el selector de arriba.`;}});
  $('#orbitpackInspectPath')?.addEventListener('click',async()=>{const path=$('#orbitpackLocalPath')?.value.trim();if(!path)return toast('Elige un archivo o introduce su ruta.','warning');await orbitpackInspectAndChoose(path);});
  $('#orbitpackBrowserFile')?.addEventListener('change',async e=>{
    const file=e.target.files?.[0];if(!file)return;
    const status=$('#orbitpackChooseStatus');
    if(!file.name.toLowerCase().endsWith('.orbitpack'))return toast('Selecciona un archivo .orbitpack.','warning');
    if(status)status.textContent='Transfiriendo el paquete al servicio local de ORBIT…';
    try{
      const response=await fetchOrbit('/api/orbitpack/upload',{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:file});
      const body=await response.json();if(!response.ok||!body.ok)throw new Error(body.error||`Error ${response.status}`);
      await orbitpackInspectAndChoose(body.path);
    }catch(err){if(status)status.textContent=`Error: ${err?.message||String(err)}`;showError(err);}
  });
}

function mediaMenu(game){
  openModal(`<div class="modal-head"><div><p class="eyebrow">IMÁGENES</p><h2>${escapeHtml(game.name)}</h2></div><button class="icon-button focusable" data-focusable data-action="close-modal">×</button></div><div class="modal-body"><div class="media-options"><button class="media-option focusable" data-focusable data-action="set-media" data-kind="cover" data-id="${game.id}"><b>Carátula local</b><span>${game.cover?'Cambiar':'Añadir'} imagen vertical</span></button><button class="media-option focusable" data-focusable data-action="set-media" data-kind="background" data-id="${game.id}"><b>Fondo local</b><span>${game.background?'Cambiar':'Añadir'} imagen panorámica</span></button><button class="media-option focusable" data-focusable data-action="set-media" data-kind="logo" data-id="${game.id}"><b>Logo local</b><span>${game.logo?'Cambiar':'Añadir'} imagen transparente</span></button><button class="media-option focusable" data-focusable data-action="set-media" data-kind="screenshot" data-id="${game.id}"><b>Captura</b><span>Añadir a la galería</span></button></div><h3>Buscar en Internet</h3><div class="button-row"><button class="secondary-button focusable" data-focusable data-action="art-search-kind" data-kind="grid" data-id="${game.id}">Carátula</button><button class="secondary-button focusable" data-focusable data-action="art-search-kind" data-kind="hero" data-id="${game.id}">Fondo</button><button class="secondary-button focusable" data-focusable data-action="art-search-kind" data-kind="logo" data-id="${game.id}">Logo</button></div><p class="muted">La búsqueda online es opcional y usa la clave de SteamGridDB configurada por el usuario.</p><div class="button-row">${['cover','background','logo'].filter(k=>game[k]).map(k=>`<button class="danger-button focusable" data-focusable data-action="remove-media" data-kind="${k}" data-id="${game.id}">Quitar ${k}</button>`).join('')}</div></div>`);
}

async function readinessModal(){
  try{
    const b=await api('/api/readiness'),r=b.result||{},problems=r.problems||[],reqs=r.requirements||[];
    const requirementMarkup=reqs.map(x=>`<article class="insight-card"><div class="insight-title"><b>${escapeHtml(x.platform)}</b><span class="status-badge ${x.ok?'ok':'warning'}">${x.ok?'Listo':'Revisar'}</span></div>${(x.items||[]).map(i=>`<div class="mini-status"><span>${i.ok?'✅':'⚠️'} ${escapeHtml(i.label)}</span><small>${escapeHtml(i.message||'')}</small></div>`).join('')}</article>`).join('');
    const problemMarkup=problems.map(x=>`<div class="list-item"><div class="list-item-main"><b>${escapeHtml(x.label||x.name||x.platform||'Revisión')}</b><small>${escapeHtml(x.message||x.detail||x.path||'Necesita atención')}</small></div><span class="status-badge warning">Revisar</span></div>`).join('');
    openModal(`<div class="modal-head"><div><p class="eyebrow">ESTADO DE ORBIT</p><h2>${r.ok?'✓ Todo correcto':'Revisión necesaria'}</h2></div><button class="icon-button focusable" data-focusable data-action="close-modal">×</button></div><div class="modal-body"><div class="info-banner ${r.ok?'success':''}"><div><b>${escapeHtml(r.summary||'Comprobación terminada')}</b><p>Se han revisado biblioteca, emuladores, archivos de sistema y portabilidad del perfil activo.</p></div></div>${requirementMarkup?`<div class="insight-grid">${requirementMarkup}</div>`:''}<div class="list-stack">${problemMarkup||'<div class="empty-state">No se han detectado incidencias.</div>'}</div></div><div class="modal-actions"><button class="secondary-button focusable" data-focusable data-action="portable-check">Ver portabilidad</button><button class="primary-button focusable" data-focusable data-action="close-modal">Entendido</button></div>`,true);
  }catch(err){showError(err);}
}

function orbitAiModal(){
  openModal(`<form id="orbitAiForm"><div class="modal-head"><div><p class="eyebrow">ORBIT AI · OFFLINE / LOCAL</p><h2>¿Qué quieres hacer?</h2></div><button type="button" class="icon-button focusable" data-focusable data-action="close-modal">×</button></div><div class="modal-body"><div class="ai-intro"><div class="ai-orb">◎</div><div><b>Asistente local de ORBIT</b><p class="muted">Entiende lenguaje natural sin depender de frases exactas. Funciona offline; el modelo local y la búsqueda web son opcionales e independientes.</p></div></div><div class="field"><label>Petición</label><textarea name="query" class="focusable" data-focusable rows="4" placeholder="Ej.: ¿Está listo mi ORBIT? · ¿Qué juegos de GameCube tengo? · Recomiéndame algo que no haya jugado"></textarea></div><div class="button-row ai-suggestions"><button type="button" class="chip focusable" data-focusable data-ai-prompt="¿Está listo mi ORBIT?">Estado de ORBIT</button><button type="button" class="chip focusable" data-focusable data-ai-prompt="¿Qué juegos no he jugado todavía?">Sin estrenar</button><button type="button" class="chip focusable" data-focusable data-ai-prompt="Recomiéndame un juego">Recomiéndame</button></div><div id="aiAnswer"></div></div><div class="modal-actions"><button class="primary-button focusable" data-focusable>Preguntar</button></div></form>`,true);
  $$('[data-ai-prompt]',$('#modal')).forEach(btn=>btn.addEventListener('click',()=>{$('#orbitAiForm').elements.query.value=btn.dataset.aiPrompt;$('#orbitAiForm').elements.query.focus();}));
  $('#orbitAiForm').addEventListener('submit',async e=>{e.preventDefault();const query=String(new FormData(e.currentTarget).get('query')||'').trim();if(!query)return;const target=$('#aiAnswer');target.innerHTML='<div class="empty-state">Analizando…</div>';try{const b=await api('/api/ai/ask',{method:'POST',body:JSON.stringify({query})}),r=b.result||{};target.innerHTML=`<article class="ai-answer"><b>ORBIT AI · ${escapeHtml(r.engine||'offline')}</b><p>${escapeHtml(r.answer||'')}</p>${(r.items||[]).length?`<div class="ai-results">${(r.items||[]).map(x=>x.id&&x.name?`<button type="button" class="list-item ai-game-result focusable" data-focusable data-action="ai-open-game" data-id="${escapeHtml(x.id)}"><span><b>${escapeHtml(x.name)}</b><small>${escapeHtml(x.platform||'')}</small></span><span>›</span></button>`:`<div class="list-item"><div class="list-item-main"><b>${escapeHtml(x.title||x.label||x.name||x.type||'Resultado')}</b><small>${escapeHtml(x.snippet||x.message||x.detail||x.url||'')}</small></div></div>`).join('')}</div>`:''}</article>`;updateFocusables();}catch(err){target.innerHTML='';showError(err);}});
}

function organizationModal(){
  const org=state.settings.organization||{},gameMap=org.platform_paths||{},emuMap=org.emulator_paths||{};
  openModal(`<div class="modal-head"><div><p class="eyebrow">ORGANIZACIÓN</p><h2>Carpetas del ORBIT receptor</h2></div><button class="icon-button focusable" data-focusable data-action="close-modal">×</button></div><div class="modal-body"><p class="muted">Cuando importes un ORBIT Pack, cada consola se colocará según estas reglas. Las carpetas automáticas de importación deben estar dentro de ORBIT para evitar escrituras accidentales fuera del USB.</p><form id="platformDestinationForm" class="organization-form"><div class="field"><label>Consola</label><select name="platform" class="focusable" data-focusable>${platformOptions('Nintendo Switch')}</select></div><div class="field wide"><label>Carpeta de juegos</label><div class="path-input"><input name="path" class="focusable" data-focusable value="${escapeHtml(gameMap['Nintendo Switch']||'@launcher/games/Nintendo Switch')}"><button type="button" class="secondary-button focusable" data-focusable data-browse="folder" data-target="path">Elegir</button></div></div><button class="primary-button focusable" data-focusable>Guardar ruta</button></form><div class="destination-list">${Object.entries(gameMap).map(([p,v])=>`<div class="list-item"><div class="list-item-main"><b>${escapeHtml(p)}</b><small>${escapeHtml(displayPath(v))}</small></div></div>`).join('')||'<div class="empty-state">Aún no has personalizado rutas. ORBIT usa games/&lt;consola&gt;.</div>'}</div></div>`,true);
  const form=$('#platformDestinationForm');
  form.elements.platform.addEventListener('change',()=>{const p=form.elements.platform.value;form.elements.path.value=gameMap[p]||`@launcher/games/${p}`;});
  form.addEventListener('submit',async e=>{e.preventDefault();const fd=Object.fromEntries(new FormData(form));try{await api('/api/organization/platform',{method:'POST',body:JSON.stringify(fd)});await loadState();organizationModal();toast('Ruta guardada','success');}catch(err){showError(err);}});
}

function themeEditorModal(theme=null){
  const t=theme||{name:'Mi tema',base:'dark',accent:'#65f4c5',accent2:'#7aa7ff',background:'#0b0f14',panel:'#141b24',text:'#f5f7fb',muted:'#9aa8b6',size:'medium',shape:'soft',spacing:'normal',shadow:'medium',animation:'smooth'};
  const options=(values,current)=>values.map(([v,l])=>`<option value="${v}" ${current===v?'selected':''}>${l}</option>`).join('');
  openModal(`<form id="themeEditorForm"><div class="modal-head"><div><p class="eyebrow">CREADOR DE TEMAS</p><h2>${theme?'Editar':'Nuevo'} tema</h2></div><button type="button" class="icon-button focusable" data-focusable data-action="close-modal">×</button></div><div class="modal-body theme-editor-layout"><div class="theme-editor-controls"><input type="hidden" name="id" value="${escapeHtml(t.id||'')}"><div class="field"><label>Nombre</label><input name="name" class="focusable" data-focusable value="${escapeHtml(t.name||'Mi tema')}"></div><div class="form-grid"><div class="field"><label>Base</label><select name="base" class="focusable" data-focusable>${options([['dark','Oscura'],['light','Clara'],['oled','OLED']],t.base)}</select></div><div class="field"><label>Tamaño</label><select name="size" class="focusable" data-focusable>${options([['small','Pequeño'],['medium','Mediano'],['large','Grande']],t.size)}</select></div><div class="field"><label>Forma</label><select name="shape" class="focusable" data-focusable>${options([['straight','Recta'],['soft','Suave'],['rounded','Redondeada'],['very-rounded','Muy redondeada']],t.shape)}</select></div><div class="field"><label>Separación</label><select name="spacing" class="focusable" data-focusable>${options([['tight','Junta'],['normal','Normal'],['wide','Amplia']],t.spacing)}</select></div><div class="field"><label>Sombras</label><select name="shadow" class="focusable" data-focusable>${options([['none','Ninguna'],['soft','Suave'],['medium','Media'],['strong','Intensa']],t.shadow)}</select></div><div class="field"><label>Animaciones</label><select name="animation" class="focusable" data-focusable>${options([['none','Ninguna'],['fast','Rápida'],['smooth','Suave'],['cinematic','Cinematográfica']],t.animation)}</select></div></div><div class="theme-color-grid">${[['accent','Principal'],['accent2','Secundario'],['background','Fondo'],['panel','Paneles'],['text','Texto'],['muted','Texto secundario']].map(([k,l])=>`<label><span>${l}</span><input name="${k}" type="color" class="focusable" data-focusable value="${escapeHtml(t[k])}"></label>`).join('')}</div></div><div id="themeLivePreview" class="theme-live-preview"><div class="preview-sidebar">ORBIT</div><div class="preview-main"><span>INICIO</span><h3>Continuar jugando</h3><div class="preview-hero"></div><div class="preview-cards"><i></i><i></i><i></i></div></div></div></div><div class="modal-actions">${theme?`<button type="button" class="danger-button focusable" data-focusable data-action="theme-delete" data-id="${escapeHtml(t.id)}">Eliminar</button><button type="button" class="secondary-button focusable" data-focusable data-action="theme-export" data-id="${escapeHtml(t.id)}">Exportar .orbittheme</button>`:''}<button class="primary-button focusable" data-focusable>Guardar tema</button></div></form>`,true);
  const form=$('#themeEditorForm'),preview=$('#themeLivePreview');
  const update=()=>{const fd=Object.fromEntries(new FormData(form));preview.style.setProperty('--p-bg',fd.background);preview.style.setProperty('--p-panel',fd.panel);preview.style.setProperty('--p-text',fd.text);preview.style.setProperty('--p-muted',fd.muted);preview.style.setProperty('--p-accent',fd.accent);preview.dataset.shape=fd.shape;preview.dataset.spacing=fd.spacing;};
  form.addEventListener('input',update);form.addEventListener('change',update);update();
  form.addEventListener('submit',async e=>{e.preventDefault();const payload=Object.fromEntries(new FormData(form));if(!payload.id)delete payload.id;try{const b=await api('/api/themes',{method:'POST',body:JSON.stringify(payload)});await loadState();closeModal();toast(`Tema guardado: ${b.theme.name}`,'success');}catch(err){showError(err);}});
}

async function gameArtSearch(game,kind='grid',providerGameId=null){
  try{
    const payload={kind};if(providerGameId!==null)payload.provider_game_id=providerGameId;
    const b=await api(`/api/games/${game.id}/art/search`,{method:'POST',body:JSON.stringify(payload)}),r=b.result||{};
    if(!r.configured){openModal(`<div class="modal-head"><div><p class="eyebrow">CARÁTULAS ONLINE</p><h2>Falta configurar SteamGridDB</h2></div><button class="icon-button focusable" data-focusable data-action="close-modal">×</button></div><div class="modal-body"><p>${escapeHtml(r.message||'Añade tu clave en Ajustes.')}</p></div><div class="modal-actions"><button class="primary-button focusable" data-focusable data-action="close-modal">Entendido</button></div>`);return;}
    const assets=r.assets||[],games=r.games||[];
    const targetKind=kind==='hero'?'background':kind==='logo'?'logo':'cover';
    openModal(`<div class="modal-head"><div><p class="eyebrow">BUSCAR EN INTERNET</p><h2>${escapeHtml(game.name)}</h2></div><button class="icon-button focusable" data-focusable data-action="close-modal">×</button></div><div class="modal-body"><div class="art-tabs"><button class="chip focusable ${kind==='grid'?'active':''}" data-focusable data-action="art-search-kind" data-id="${game.id}" data-kind="grid">Carátula</button><button class="chip focusable ${kind==='hero'?'active':''}" data-focusable data-action="art-search-kind" data-id="${game.id}" data-kind="hero">Fondo</button><button class="chip focusable ${kind==='logo'?'active':''}" data-focusable data-action="art-search-kind" data-id="${game.id}" data-kind="logo">Logo</button></div>${games.length>1?`<div class="provider-games"><small>Coincidencia:</small>${games.map(x=>`<button class="chip focusable" data-focusable data-action="art-provider" data-id="${game.id}" data-kind="${kind}" data-provider-id="${x.id}">${escapeHtml(x.name)}</button>`).join('')}</div>`:''}<div class="art-grid">${assets.map(x=>`<button class="art-result focusable" data-focusable data-action="art-apply" data-id="${game.id}" data-kind="${targetKind}" data-url="${escapeHtml(x.url)}"><img src="${escapeHtml(x.thumb||x.url)}" alt=""><small>${escapeHtml([x.width&&x.height?`${x.width}×${x.height}`:'',x.style||''].filter(Boolean).join(' · '))}</small></button>`).join('')||'<div class="empty-state">No se han encontrado imágenes para esta coincidencia.</div>'}</div></div>`,true);
  }catch(err){showError(err);}
}

async function loadGameInsights(game){
  const perf=$('#gamePerformance'),req=$('#gameRequirements');if(!perf&&!req)return;
  try{
    const [p,r]=await Promise.all([api(`/api/games/${game.id}/performance`),api(`/api/games/${game.id}/requirements`)]);
    if(perf){const x=p.result||{};perf.innerHTML=`<div class="insight-title"><b>${x.icon||'⚪'} Rendimiento</b><span class="status-badge ${x.score>=3?'ok':x.score===2?'warning':x.score===null?'':'error'}">${escapeHtml(x.label||'Sin datos')}</span></div><p>${escapeHtml((x.reasons||[]).join(' '))}</p><small>${escapeHtml(x.disclaimer||'')}</small>`;}
    if(req){const x=r.result||{};req.innerHTML=x.required?`<div class="insight-title"><b>Archivos necesarios</b><span class="status-badge ${x.ok?'ok':'warning'}">${x.ok?'Listo':'Falta algo'}</span></div>${(x.items||[]).map(i=>`<div class="mini-status"><span>${i.ok?'✅':'⚠️'} ${escapeHtml(i.label)}</span><small>${escapeHtml(i.message||'')}</small></div>`).join('')}<small>${escapeHtml(x.legal_note||'')}</small>`:`<div class="insight-title"><b>Archivos necesarios</b><span class="status-badge ok">Sin requisitos extra</span></div>`;}
  }catch(err){if(perf)perf.innerHTML=`<small>${escapeHtml(err.message||String(err))}</small>`;}
}

function detailModal(game){
  const em=emulatorById(game.emulator_id),bg=mediaUrl(game.background,game.background_version),logo=mediaUrl(game.logo,game.logo_version);
  openModal(`<div class="detail-shell" ${bg?`style="--detail-bg:url('${escapeHtml(bg)}')"`:''}><div class="detail-backdrop"></div><div class="modal-head detail-head"><div><p class="eyebrow">${escapeHtml(game.platform)}</p><h2>Detalles</h2></div><button class="icon-button focusable" data-focusable data-action="close-modal">×</button></div><div class="modal-body"><div class="game-detail-v2"><div class="detail-cover">${coverMarkup(game)}</div><div class="detail-info">${logo?`<img class="detail-logo" src="${escapeHtml(logo)}" alt="${escapeHtml(game.name)}">`:`<h2>${escapeHtml(game.name)}</h2>`}<p>${escapeHtml(game.description||'Sin descripción.')}</p><div class="tag-row">${(game.tags||[]).map(t=>`<span class="tag">${escapeHtml(t)}</span>`).join('')}</div><div class="detail-facts"><div class="detail-fact"><small>Tiempo jugado</small><b>${formatDuration(game.play_time_seconds)}</b></div><div class="detail-fact"><small>Estado</small><b>${game.status==='completed'?'Completado':game.status==='playing'?'Jugando':'Pendiente'}</b></div><div class="detail-fact"><small>Emulador</small><b>${escapeHtml(em?.name||(game.platform==='PC'?'Nativo':'Sin configurar'))}</b></div><div class="detail-fact"><small>Edición</small><b>${escapeHtml([game.region,game.revision].filter(Boolean).join(' · ')||'—')}</b></div></div><div class="insight-grid"><article id="gamePerformance" class="insight-card"><div class="empty-state">Analizando rendimiento…</div></article><article id="gameRequirements" class="insight-card"><div class="empty-state">Comprobando firmware/keys…</div></article></div><div class="media-strip">${(game.screenshots||[]).map((x,i)=>`<div class="shot"><img src="${escapeHtml(mediaUrl(x))}"><button class="mini-remove focusable" data-focusable data-action="remove-media" data-id="${game.id}" data-kind="screenshot" data-index="${i}">×</button></div>`).join('')}</div></div></div></div><div class="modal-actions modal-actions-wrap"><button class="secondary-button focusable" data-focusable data-action="edit-game" data-id="${game.id}">✎ Editar</button><button class="secondary-button focusable" data-focusable data-action="media-menu" data-id="${game.id}">🖼 Imágenes</button><button class="secondary-button focusable" data-focusable data-action="art-search-kind" data-kind="grid" data-id="${game.id}">🌐 Buscar carátula</button>${game.save_path?`<button class="secondary-button focusable" data-focusable data-action="backups" data-id="${game.id}">☁ Partidas</button>`:''}<button class="secondary-button focusable" data-focusable data-action="favorite" data-id="${game.id}">${game.favorite?'★ Quitar favorito':'☆ Favorito'}</button>${!game.demo?`<button class="danger-button focusable" data-focusable data-action="remove-game" data-id="${game.id}">Quitar</button>`:''}${game.demo?'<button class="primary-button focusable" data-focusable data-action="add-game">＋ Añadir juego real</button>':game.available?`<button class="primary-button focusable" data-focusable data-action="launch" data-id="${game.id}">▶ Jugar</button>`:'<button class="primary-button" disabled>⚠ Revisa configuración</button>'}</div></div>`,true);
  loadGameInsights(game);
}

async function handleAction(el){const action=el.dataset.action,id=el.dataset.id,game=id?gameById(id):null;try{
  if(action==='close-modal')return closeModal(); if(action==='add-game'||action==='setup-wizard')return setupWizard(); if(action==='edit-game')return gameForm(game); if(action==='add-folder')return addFolderModal(); if(action==='add-emulator')return emulatorForm(); if(action==='edit-emulator')return emulatorForm(emulatorById(id)); if(action==='media-menu')return mediaMenu(game); if(action==='launch')return launchGame(id);
  if(action==='stop-game'){if(state.settings.confirm_stop_game!==false&&!confirm('¿Cerrar este juego o emulador desde ORBIT?'))return;await api(`/api/games/${id}/stop`,{method:'POST',body:JSON.stringify({confirmed:true})});toast('Cerrando juego/emulador…','success');setTimeout(()=>loadState().catch(()=>{}),600);return;}
  if(action==='favorite'){await api(`/api/games/${id}/favorite`,{method:'POST',body:'{}'});await loadState();if(!$('#modalBackdrop').hidden)detailModal(gameById(id));return;}
  if(action==='remove-game'){if(!confirm('¿Quitar este juego de la biblioteca? El archivo original NO se borrará.'))return;await api(`/api/games/${id}`,{method:'DELETE'});closeModal();await loadState();return toast('Quitado de la biblioteca','success');}
  if(action==='set-media'){const kind=el.dataset.kind;const b=await api('/api/dialog/cover',{method:'POST',body:'{}'});if(!b.path)return;const endpoint=kind==='cover'?`/api/games/${id}/cover`:`/api/games/${id}/media/${kind}`;await api(endpoint,{method:'POST',body:JSON.stringify({path:b.path})});await loadState();mediaMenu(gameById(id));return toast('Imagen guardada','success');}
  if(action==='remove-media'){const kind=el.dataset.kind,index=el.dataset.index;const endpoint=kind==='cover'?`/api/games/${id}/cover`:`/api/games/${id}/media/${kind}${kind==='screenshot'?`?index=${index}`:''}`;await api(endpoint,{method:'DELETE'});await loadState();return detailModal(gameById(id));}
  if(action==='backup'){await api(`/api/games/${id}/backup`,{method:'POST',body:JSON.stringify({reason:'manual'})});toast('Backup creado','success');if(!$('#modalBackdrop').hidden)await backupsModal(gameById(id));return;}
  if(action==='backups')return backupsModal(game);
  if(action==='restore'){if(!confirm('¿Restaurar este backup? ORBIT hará una copia de seguridad de las partidas actuales antes de sustituirlas.'))return;await api(`/api/games/${id}/restore`,{method:'POST',body:JSON.stringify({backup_id:el.dataset.backup,confirmed:true})});toast('Backup restaurado','success');return backupsModal(gameById(id));}
  if(action==='sync-to-usb'){await api(`/api/games/${id}/sync`,{method:'POST',body:JSON.stringify({direction:'pc_to_usb'})});return toast('Partidas copiadas al USB','success');}
  if(action==='sync-to-pc'){if(!confirm('¿Copiar las partidas del USB al PC? ORBIT hará un backup de seguridad de la copia actual.'))return;await api(`/api/games/${id}/sync`,{method:'POST',body:JSON.stringify({direction:'usb_to_pc',confirmed:true})});return toast('Partidas copiadas al PC','success');}
  if(action==='metadata-guess'){if(!id)return;const b=await api(`/api/games/${id}/metadata-guess`,{method:'POST',body:'{}'});const form=$('#gameForm');if(form&&b.guess?.name)form.elements.name.value=b.guess.name;if(b.guess?.cover_candidate&&confirm(`Se encontró una carátula local. ¿Usarla?`)){await api(`/api/games/${id}/cover`,{method:'POST',body:JSON.stringify({path:b.guess.cover_candidate})});toast('Carátula detectada','success');}return;}
  if(action==='edit-collection')return collectionModal(state.collections.find(c=>c.id===id)); if(action==='delete-collection'){if(!confirm('¿Eliminar esta colección? Los juegos no se borrarán.'))return;await api(`/api/collections/${id}`,{method:'DELETE'});await loadState();return;}
  if(action==='add-profile')return profileCreateModal();
  if(action==='profile-manager')return profileManagerModal();
  if(action==='edit-profile')return profileEditModal(id);
  if(action==='select-profile')return selectProfileAndReload(id,true);
  if(action==='profile-photo')return chooseProfilePhoto(id);
  if(action==='delete-profile')return deleteProfile(id);
  if(action==='open-emulator-center')return emulatorCenterModal();
  if(action==='open-emulator-site'){const b=await api('/api/emulator-sites/open',{method:'POST',body:JSON.stringify({id:el.dataset.site})});return toast(`${b.result.name} abierto en el navegador`,'success');}
  if(action==='prepare-emulator-folders'){const b=await api('/api/emulators/install/prepare',{method:'POST',body:'{}'});toast(`Carpetas preparadas: ${b.result.total}`,'success');await loadState();return emulatorCenterModal();}
  if(action==='install-emulator-package'){toast('Descargando desde la fuente oficial…');const b=await api(`/api/emulators/install/${el.dataset.package}`,{method:'POST',body:'{}'});if(b.result.status==='manual'){toast('Este emulador requiere instalación manual desde su web oficial');}else toast(`${b.result.id}: ${b.result.status}`,'success');await loadState();return emulatorCenterModal();}
  if(action==='install-all-emulators'){if(!confirm('ORBIT intentará descargar solo paquetes ZIP reconocibles desde fuentes oficiales. Los que requieran instalador manual quedarán preparados en su carpeta. ¿Continuar?'))return;toast('Instalando emuladores recomendados…');const b=await api('/api/emulators/install/all',{method:'POST',body:'{}'});await loadState();emulatorCenterModal();return toast(`Instalados: ${b.result.installed} · Manuales: ${b.result.manual} · Errores: ${b.result.errors}`,b.result.errors?'':'success');}
  if(action==='controller-test')return controllerTestModal();
  if(action==='open-help'){closeModal();return setView('help');}
  if(action==='tutorial')return tutorialModal();
  if(action==='controller-mapping')return controllerMappingModal();
  if(action==='setup-pc')return quickPcModal();
  if(action==='setup-rom')return quickRomModal();
  if(action==='setup-folder')return addFolderModal();
  if(action==='setup-emulator')return emulatorForm();
  if(action==='setup-steam'){closeModal();const b=await api('/api/import/steam-preview');return importPreviewModal(b.items||[],'Steam');}
  if(action==='setup-import-folder'){closeModal();const d=await api('/api/dialog/folder',{method:'POST',body:'{}'});if(!d.path)return setupWizard();const b=await api('/api/import/folder-preview',{method:'POST',body:JSON.stringify({path:d.path})});return importPreviewModal(b.items||[],'Carpeta local');}
  if(action==='setup-finish'){await saveSettings({setup_complete:true});return closeModal();}
  if(action==='choose-theme'){const key=el.dataset.theme,custom=(state.customThemes||[]).find(t=>t.id===key);if(!THEME_DEFS[key]&&!custom)return;await saveSettings({theme:key,accent:custom?.accent||THEME_DEFS[key]?.accent||state.settings.accent});return;}
  if(action==='choose-mode'){const key=el.dataset.mode;if(!MODE_DEFS[key])return;await saveSettings({interface_mode:key});return;}
  if(action==='test-emulator'){const b=await api(`/api/emulators/${id}/test`,{method:'POST',body:'{}'});return toast(b.result.ok?'Emulador localizado correctamente':b.result.detail,b.result.ok?'success':'error');}
  if(action==='delete-emulator'){if(!confirm('¿Eliminar este emulador de ORBIT? No se borrará su archivo.'))return;await api(`/api/emulators/${id}`,{method:'DELETE'});await loadState();return;}
  if(action==='portable-check')return portableCheckModal();
  if(action==='duplicates')return duplicatesModal();
  if(action==='recovery-center')return recoveryCenterModal();
  if(action==='recovery-create'){const b=await api('/api/recovery/create',{method:'POST',body:JSON.stringify({reason:'manual'})});toast(`Punto creado: ${b.result.filename}`,'success');return recoveryCenterModal();}
  if(action==='recovery-restore'){if(!confirm('ORBIT creará un rollback del estado actual y restaurará este punto. ¿Continuar?'))return;const b=await api('/api/recovery/restore',{method:'POST',body:JSON.stringify({path:el.dataset.path,confirmed:true})});closeModal();await loadState();return toast(`Restaurado: ${b.result.restored}`,'success');}
  if(action==='orbitpack-export')return orbitpackExportModal();
  if(action==='orbitpack-import')return orbitpackImportStart();
  if(action==='readiness')return readinessModal();
  if(action==='orbit-ai')return orbitAiModal();
  if(action==='steamgrid-clear'){await saveSettings({cover_search:{api_key:'',provider:'steamgriddb'}});return toast('Clave de SteamGridDB eliminada','success');}
  if(action==='organization')return organizationModal();
  if(action==='theme-editor'){const current=(state.customThemes||[]).find(t=>t.id===state.settings.theme);return themeEditorModal(current||null);}
  if(action==='theme-delete'){if(!confirm('¿Eliminar este tema personalizado?'))return;await api(`/api/themes/${encodeURIComponent(id)}`,{method:'DELETE'});closeModal();await loadState();return toast('Tema eliminado','success');}
  if(action==='theme-export'){const b=await api('/api/themes/export',{method:'POST',body:JSON.stringify({id})});return toast(`Tema exportado: ${b.result.filename}`,'success');}
  if(action==='art-search-kind')return gameArtSearch(game,String(el.dataset.kind||'grid'));
  if(action==='art-provider')return gameArtSearch(game,String(el.dataset.kind||'grid'),Number(el.dataset.providerId));
  if(action==='art-apply'){const b=await api(`/api/games/${id}/art/apply`,{method:'POST',body:JSON.stringify({kind:el.dataset.kind,url:el.dataset.url})});await loadState();toast('Imagen guardada','success');return detailModal(gameById(id));}
  if(action==='ai-open-game'){const g=gameById(id);if(g)return detailModal(g);}
  if(action==='storage'){const b=await api('/api/storage');state.storage=b.storage;renderSettings();updateFocusables();return;}
  if(action==='import-steam'){const b=await api('/api/import/steam-preview');return importPreviewModal(b.items||[],'Steam');}
  if(action==='import-folder'){const d=await api('/api/dialog/folder',{method:'POST',body:'{}'});if(!d.path)return;const b=await api('/api/import/folder-preview',{method:'POST',body:JSON.stringify({path:d.path})});return importPreviewModal(b.items||[],'Carpeta local');}
  if(action==='apply-import'){const items=JSON.parse($('#modal').dataset.importItems||'[]');const selected=$$('[data-import-index]:checked',$('#modal')).map(x=>items[Number(x.dataset.importIndex)]).filter(Boolean);const b=await api('/api/import/apply',{method:'POST',body:JSON.stringify({items:selected})});closeModal();await loadState();return toast(`${b.result.added} juegos importados`,'success');}
}catch(err){showError(err);}}

function bindEvents(){document.addEventListener('click',async e=>{const browse=e.target.closest('[data-browse]');if(browse){e.preventDefault();try{await browseField(browse.dataset.browse,browse.dataset.target);}catch(err){showError(err);}return;}const view=e.target.closest('[data-view]');if(view){setView(view.dataset.view);return;}const card=e.target.closest('[data-game-id]');if(card&&!e.target.closest('[data-action]')){const g=gameById(card.dataset.gameId);if(g)detailModal(g);return;}const smart=e.target.closest('[data-smart]');if(smart){state.smart=smart.dataset.smart||'all';if(smart.hasAttribute('data-go-library'))setView('library');else renderLibrary();updateFocusables();return;}const platform=e.target.closest('[data-platform]');if(platform){state.platform=platform.dataset.platform;renderLibrary();updateFocusables();return;}const action=e.target.closest('[data-action]');if(action){e.preventDefault();await handleAction(action);return;}});
  $('#globalSearch').addEventListener('input',e=>{state.search=e.target.value;if(state.view!=='library')setView('library');else renderLibrary();});
  $('#sortSelect').addEventListener('change',e=>{state.sort=e.target.value;renderLibrary();});
  $('#refreshButton').addEventListener('click',scanLibrary); $('#addGameButton').addEventListener('click',setupWizard); if($('#setupButton'))$('#setupButton').addEventListener('click',setupWizard); $('#randomButton').addEventListener('click',()=>{const games=filteredGames().filter(g=>!g.demo&&g.available);if(!games.length)return toast('No hay juegos disponibles con los filtros actuales','error');detailModal(games[Math.floor(Math.random()*games.length)]);});
  $('#newCollectionButton').addEventListener('click',()=>collectionModal()); $('#runDiagnosticsButton').addEventListener('click',()=>renderDiagnostics(true).catch(showError));
  $('#fullscreenButton').addEventListener('click',async()=>{try{if(!document.fullscreenElement)await document.documentElement.requestFullscreen();else await document.exitFullscreen();}catch(err){showError(err);}});
  $('#exitButton').addEventListener('click',async()=>{if(!confirm('¿Salir de ORBIT?'))return;try{await api('/api/shutdown',{method:'POST',body:'{}'});}catch(_){}document.body.innerHTML='<div class="closed"><div><h1>ORBIT cerrado</h1><p>Ya puedes cerrar esta ventana.</p></div></div>';setTimeout(()=>window.close(),300);});
  $('#modalBackdrop').addEventListener('click',e=>{if(e.target===$('#modalBackdrop'))closeModal();});
  document.addEventListener('change',async e=>{try{if(e.target.id==='themeSelect'){const key=e.target.value;await saveSettings({theme:key,accent:THEME_DEFS[key]?.accent||state.settings.accent});}if(e.target.id==='steamGridKey'&&e.target.value.trim())await saveSettings({cover_search:{api_key:e.target.value.trim(),provider:'steamgriddb'}});if(e.target.id==='aiLocalModel')await saveSettings({ai:{local_model:{model:e.target.value}}});if(e.target.id==='aiLocalEndpoint')await saveSettings({ai:{local_model:{endpoint:e.target.value}}});if(e.target.id==='accentPicker')await saveSettings({accent:e.target.value});if(e.target.id==='uiScale')await saveSettings({ui_scale:Number(e.target.value)});if(e.target.id==='profileSelect'){await selectProfileAndReload(e.target.value,false);toast('Perfil cambiado','success');}if(e.target.id==='controllerDeadzone'){const c=structuredClone(state.settings.controller||{});const p=(c.profiles||[]).find(x=>x.id===c.active_profile);if(p)p.deadzone=Number(e.target.value);await saveSettings({controller:c});}if(e.target.matches('[data-default-emulator]')){await api('/api/default-emulator',{method:'POST',body:JSON.stringify({platform:e.target.dataset.platform,emulator_id:e.target.value||null})});await loadState();}}catch(err){showError(err);}});
  document.addEventListener('click',async e=>{const t=e.target.closest('[data-setting-toggle]');if(t){const key=t.dataset.settingToggle,val=t.getAttribute('aria-pressed')!=='true';try{await saveSettings({[key]:val});if(key==='start_fullscreen'){try{if(val&&!document.fullscreenElement)await document.documentElement.requestFullscreen();if(!val&&document.fullscreenElement)await document.exitFullscreen();}catch(_){}}}catch(err){showError(err);}return;}const ai=e.target.closest('[data-ai-toggle]');if(ai){const key=ai.dataset.aiToggle,val=ai.getAttribute('aria-pressed')!=='true';try{if(key==='local_model')await saveSettings({ai:{local_model:{enabled:val}}});if(key==='online_search')await saveSettings({ai:{online_search:{enabled:val}}});}catch(err){showError(err);}return;}const st=e.target.closest('[data-save-toggle]');if(st){const key=st.dataset.saveToggle,val=st.getAttribute('aria-pressed')!=='true';try{await saveSettings({saves:{[key]:val}});}catch(err){showError(err);}}});
}

function updateFocusables(){state.focusables=$$('[data-focusable]').filter(el=>!el.disabled&&el.offsetParent!==null);state.focusIndex=Math.min(state.focusIndex||0,Math.max(0,state.focusables.length-1));}
function focusElement(el){if(!el)return;$$('.is-controller-focus').forEach(x=>x.classList.remove('is-controller-focus'));el.classList.add('is-controller-focus');el.focus({preventScroll:true});el.scrollIntoView({block:'nearest',inline:'nearest',behavior:state.settings.reduce_motion?'auto':'smooth'});state.focusIndex=Math.max(0,state.focusables.indexOf(el));}
function moveFocus(dx,dy){updateFocusables();const cur=state.focusables[state.focusIndex]||document.activeElement;if(!cur||!state.focusables.length)return focusElement(state.focusables[0]);let current=state.focusables.indexOf(cur);if(current<0)current=0;const rects=state.focusables.map(el=>{const r=el.getBoundingClientRect();return {left:r.left,top:r.top,width:r.width,height:r.height};});const next=window.OrbitNavigation?.bestSpatialIndex(rects,current,dx,dy)??-1;if(next>=0)focusElement(state.focusables[next]);}
function back(){if(!$('#modalBackdrop').hidden)return closeModal();if(state.view!=='home')setView('home');}
function setInputMode(mode,label=''){
  const nav=state.settings.controller?.navigation||{};
  if(nav.auto_input_mode===false&&state.inputMode&&state.inputMode!==mode)return;
  if(state.inputMode===mode&&!label)return;
  state.inputMode=mode;
  document.body.classList.toggle('controller-mode',mode==='gamepad'&&nav.hide_cursor_on_gamepad!==false);
  document.body.classList.toggle('mouse-mode',mode==='mouse');
  document.body.classList.toggle('keyboard-mode',mode==='keyboard');
  if(mode!=='gamepad'){$$('.is-controller-focus').forEach(x=>x.classList.remove('is-controller-focus'));hideGamepadPointer();}
  if(nav.show_input_indicator!==false){
    const el=$('#inputModeIndicator');if(el){el.hidden=false;el.textContent=label||(mode==='gamepad'?'🎮 Mando':mode==='keyboard'?'⌨ Teclado':'🖱 Ratón');clearTimeout(state.inputIndicatorTimer);state.inputIndicatorTimer=setTimeout(()=>{el.hidden=true;},1100);}
  }
}

function gamepadStyle(gp){
  const configured=state.settings.controller?.navigation?.button_style||'auto';
  return window.OrbitNavigation?.gamepadStyle(gp?.id||'',configured)||'xbox';
}
function updateGamepadHints(style){
  const labels=window.OrbitNavigation?.gamepadLabels(style)||{accept:'A',back:'B',search:'Y',menu:'X',favorite:'LB'};
  const ids={hintAccept:'accept',hintBack:'back',hintSearch:'search',hintMenu:'menu',hintFavorite:'favorite'};
  Object.entries(ids).forEach(([id,key])=>{const el=$('#'+id);if(el)el.textContent=labels[key];});
}
function hideGamepadPointer(){state.gamepadPointerActive=false;const el=$('#gamepadPointer');if(el)el.hidden=true;}
function moveGamepadPointer(gp,dz,ts){
  const rawX=gp.axes?.[2]||0,rawY=gp.axes?.[3]||0,n=window.OrbitNavigation;
  const x=n?.applyDeadzone(rawX,Math.min(.45,dz*.65))??0,y=n?.applyDeadzone(rawY,Math.min(.45,dz*.65))??0;
  if(!x&&!y){state.gamepadPointerTs=ts;return false;}
  if(!state.gamepadPointerActive){state.gamepadPointerX=window.innerWidth/2;state.gamepadPointerY=window.innerHeight/2;state.gamepadPointerActive=true;}
  const dt=Math.min(34,Math.max(8,ts-(state.gamepadPointerTs||ts)));state.gamepadPointerTs=ts;
  state.gamepadPointerX=Math.max(4,Math.min(window.innerWidth-4,state.gamepadPointerX+x*dt*.75));
  state.gamepadPointerY=Math.max(4,Math.min(window.innerHeight-4,state.gamepadPointerY+y*dt*.75));
  const el=$('#gamepadPointer');if(el){el.hidden=false;el.style.left=state.gamepadPointerX+'px';el.style.top=state.gamepadPointerY+'px';}
  return true;
}

function navPressed(now,key,ts){
  const nav=state.settings.controller?.navigation||{},held=state.navHeld[key];
  if(!now){delete state.navHeld[key];return false;}
  if(!held){state.navHeld[key]={started:ts,last:ts};return true;}
  const delay=Number(nav.repeat_delay_ms||360),interval=Number(nav.repeat_interval_ms||110);
  if(ts-held.started>=delay&&ts-held.last>=interval){held.last=ts;return true;}return false;
}

function installNavigation(){
  let lastPointer={x:null,y:null};
  const activatePointer=e=>{const x=Number(e.clientX||0),y=Number(e.clientY||0);if(lastPointer.x===null||Math.hypot(x-lastPointer.x,y-lastPointer.y)>=2){lastPointer={x,y};setInputMode('mouse');}};
  document.addEventListener('pointermove',activatePointer,{passive:true});
  document.addEventListener('pointerdown',e=>{lastPointer={x:e.clientX,y:e.clientY};setInputMode('mouse');},{passive:true});
  document.addEventListener('wheel',()=>setInputMode('mouse'),{passive:true});
  document.addEventListener('keydown',e=>{
    if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;
    setInputMode('keyboard');
    if(e.key==='ArrowLeft'){e.preventDefault();moveFocus(-1,0);}if(e.key==='ArrowRight'){e.preventDefault();moveFocus(1,0);}if(e.key==='ArrowUp'){e.preventDefault();moveFocus(0,-1);}if(e.key==='ArrowDown'){e.preventDefault();moveFocus(0,1);}if(['Escape','Backspace'].includes(e.key)){e.preventDefault();if(!$('#controllerMenu').hidden)return closeControllerMenu();back();}
  });
  window.addEventListener('gamepadconnected',e=>{state.controllerIndex=e.gamepad.index;$('#controllerStatus span:last-child').textContent=e.gamepad.id||'Mando';state.gamepadPrev={};state.navHeld={};const style=gamepadStyle(e.gamepad);updateGamepadHints(style);setInputMode('gamepad',`🎮 ${style==='playstation'?'PlayStation':style==='nintendo'?'Nintendo':'Xbox'}`);});
  window.addEventListener('gamepaddisconnected',e=>{if(state.controllerIndex===e.gamepad.index)state.controllerIndex=null;$('#controllerStatus span:last-child').textContent='Sin mando';state.gamepadPrev={};state.navHeld={};hideGamepadPointer();if(state.inputMode==='gamepad')setInputMode('mouse','🖱 Ratón');});
  function loop(ts){
    const pads=navigator.getGamepads?.()||[],gp=state.controllerIndex!=null?pads[state.controllerIndex]:[...pads].find(Boolean);
    if(gp){
      state.controllerIndex=gp.index;updateControllerTester(gp);
      const prof=(state.settings.controller?.profiles||[]).find(p=>p.id===state.settings.controller?.active_profile)||(state.settings.controller?.profiles||[])[0]||{};
      const style=gamepadStyle(gp),configuredMap=prof.mapping||{accept:0,back:1,menu:2,search:3,favorite:4};
      const standardMap=(configuredMap.accept??0)===0&&(configuredMap.back??1)===1&&(configuredMap.menu??2)===2&&(configuredMap.search??3)===3&&(configuredMap.favorite??4)===4;
      const map=style==='nintendo'&&standardMap?{...configuredMap,accept:1,back:0}:configuredMap,shortcuts=state.settings.controller?.shortcuts||{},dz=Number(prof.deadzone||.55);
      const now={left:gp.axes[0]<-dz||gp.buttons[14]?.pressed,right:gp.axes[0]>dz||gp.buttons[15]?.pressed,up:gp.axes[1]<-dz||gp.buttons[12]?.pressed,down:gp.axes[1]>dz||gp.buttons[13]?.pressed,accept:gp.buttons[map.accept??0]?.pressed,back:gp.buttons[map.back??1]?.pressed,menu:gp.buttons[map.menu??2]?.pressed,search:gp.buttons[map.search??3]?.pressed,favorite:gp.buttons[map.favorite??4]?.pressed};
      updateGamepadHints(style);const pointerMoved=moveGamepadPointer(gp,dz,ts);if(Object.values(now).some(Boolean)||pointerMoved)setInputMode('gamepad',`🎮 ${style==='playstation'?'PlayStation':style==='nintendo'?'Nintendo':'Xbox'}`);
      for(const k of ['left','right','up','down'])if(navPressed(now[k],k,ts))moveFocus(k==='left'?-1:k==='right'?1:0,k==='up'?-1:k==='down'?1:0);
      if(now.accept&&!state.gamepadPrev.accept){if(state.gamepadPointerActive){const hit=document.elementFromPoint(state.gamepadPointerX,state.gamepadPointerY)?.closest?.('[data-focusable]');if(hit&&!hit.disabled){focusElement(hit);hideGamepadPointer();}}else{const target=document.querySelector('.is-controller-focus')||document.activeElement;if(target?.click)target.click();}}
      if(now.back&&!state.gamepadPrev.back){if(!$('#controllerMenu').hidden)closeControllerMenu();else back();}
      if(now.search&&!state.gamepadPrev.search&&shortcuts.search_enabled!==false&&$('#profileGate').hidden)openControllerSearch();
      if(now.menu&&!state.gamepadPrev.menu&&shortcuts.menu_enabled!==false&&$('#profileGate').hidden){if($('#controllerMenu').hidden)openControllerMenu();else closeControllerMenu();}
      if(now.favorite&&!state.gamepadPrev.favorite&&shortcuts.favorite_enabled!==false){const el=document.querySelector('.is-controller-focus[data-game-id]');if(el){const g=gameById(el.dataset.gameId);if(g&&!g.demo)api(`/api/games/${g.id}/favorite`,{method:'POST',body:'{}'}).then(loadState).catch(showError);}}
      state.gamepadPrev=now;
    }else if(state.controllerTester)updateControllerTester(null);
    requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);
}


async function init(){bindEvents();bindV030Events();installNavigation();try{await loadState();}catch(err){showError(err);$('#homeSections').innerHTML='<div class="empty-state">No se pudo cargar ORBIT. Usa Diagnóstico o launcher_debug.bat.</div>';return;}if(state.safeMode)toast('ORBIT iniciado en modo seguro','success');const gateShown=showProfileGate();if(!gateShown){const start=state.settings.start_view||'home';setView(start);}updateFocusables();setInterval(async()=>{try{const b=await api('/api/sessions');const before=state.activeSessions.length;state.activeSessions=b.sessions||[];if(state.view==='home'&&before!==state.activeSessions.length)renderHome();$('#activeSessionHint').textContent=state.activeSessions.length?`▶ ${state.activeSessions.length} juego activo`:'';}catch(_){}},10000);}

document.addEventListener('DOMContentLoaded',init);
